# --------------------------------------------------------------------------
# Finding model
# --------------------------------------------------------------------------

function Add-Finding {
    <#
        .SYNOPSIS
        Records a single observation. Everything the report shows comes from here.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Category,
        [Parameter(Mandatory)][string]$Title,
        [ValidateSet('Critical','High','Medium','Low','Info')]
        [string]$Severity = 'Info',
        [string]$Detail = '',
        [string]$Recommendation = '',
        [object]$Evidence,
        [string]$Check = ''
    )

    $evidencePairs = New-Object System.Collections.ArrayList
    if ($null -ne $Evidence) {
        if ($Evidence -is [System.Collections.IDictionary]) {
            foreach ($key in $Evidence.Keys) {
                $value = $Evidence[$key]
                if ($null -eq $value) { continue }
                if ($value -is [array]) { $value = ($value | ForEach-Object { "$_" }) -join ', ' }
                $text = "$value".Trim()
                if ($text.Length -eq 0) { continue }
                $null = $evidencePairs.Add([pscustomobject]@{ Name = "$key"; Value = $text })
            }
        }
        else {
            $null = $evidencePairs.Add([pscustomobject]@{ Name = 'Detail'; Value = "$Evidence" })
        }
    }

    $finding = [pscustomobject]@{
        Id             = [guid]::NewGuid().ToString('N').Substring(0, 8)
        Category       = $Category
        Check          = $Check
        Title          = $Title
        Severity       = $Severity
        Rank           = $script:SeverityRank[$Severity]
        Detail         = $Detail
        Recommendation = $Recommendation
        Evidence       = @($evidencePairs)
    }

    $null = $script:Findings.Add($finding)
    Write-FindingToConsole -Finding $finding
    return $finding
}

function Write-FindingToConsole {
    param([Parameter(Mandatory)][object]$Finding)

    if ($script:Quiet) { return }
    if ($script:SeverityRank[$Finding.Severity] -gt $script:SeverityRank[$script:ConsoleThreshold]) { return }

    $color = switch ($Finding.Severity) {
        'Critical' { 'Magenta' }
        'High'     { 'Red' }
        'Medium'   { 'Yellow' }
        'Low'      { 'Cyan' }
        default    { 'DarkGray' }
    }
    Write-Host ("  [{0,-8}] {1}" -f $Finding.Severity.ToUpper(), $Finding.Title) -ForegroundColor $color
    if ($Finding.Detail) {
        Write-Host ("             {0}" -f $Finding.Detail) -ForegroundColor DarkGray
    }
}

function Write-ScanLog {
    param([string]$Message, [string]$Level = 'Info')

    if ($script:Quiet) { return }
    $color = switch ($Level) {
        'Step'  { 'White' }
        'Warn'  { 'Yellow' }
        'Error' { 'Red' }
        'Good'  { 'Green' }
        default { 'DarkGray' }
    }
    $prefix = if ($Level -eq 'Step') { "`n==> " } else { '    ' }
    Write-Host ("{0}{1}" -f $prefix, $Message) -ForegroundColor $color
}

function Invoke-Check {
    <#
        .SYNOPSIS
        Runs one check in a guard so a single failure never aborts the scan.
        Missing cmdlets and access-denied are normal on some SKUs.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][scriptblock]$Body
    )

    $null = $script:ChecksRun.Add($Name)
    try {
        & $Body
    }
    catch {
        $null = $script:CheckErrors.Add([pscustomobject]@{
            Check   = $Name
            Message = $_.Exception.Message
        })
        Write-ScanLog -Message "check '$Name' could not complete: $($_.Exception.Message)" -Level 'Warn'
    }
}

# --------------------------------------------------------------------------
# Environment
# --------------------------------------------------------------------------

function Test-IsElevated {
    try {
        $identity  = [Security.Principal.WindowsIdentity]::GetCurrent()
        $principal = New-Object Security.Principal.WindowsPrincipal($identity)
        return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    }
    catch { return $false }
}

function Get-HostSummary {
    $os  = $null
    $cs  = $null
    try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch { }
    try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop } catch { }

    [pscustomobject]@{
        ComputerName  = $env:COMPUTERNAME
        UserName      = "$env:USERDOMAIN\$env:USERNAME"
        Elevated      = Test-IsElevated
        OS            = if ($os) { $os.Caption } else { 'unknown' }
        OSVersion     = if ($os) { $os.Version } else { [string][Environment]::OSVersion.Version }
        InstallDate   = if ($os) { $os.InstallDate } else { $null }
        LastBoot      = if ($os) { $os.LastBootUpTime } else { $null }
        Domain        = if ($cs) { $cs.Domain } else { 'unknown' }
        PartOfDomain  = if ($cs) { $cs.PartOfDomain } else { $false }
        Manufacturer  = if ($cs) { $cs.Manufacturer } else { 'unknown' }
        Model         = if ($cs) { $cs.Model } else { 'unknown' }
        PSVersion     = $PSVersionTable.PSVersion.ToString()
    }
}

# --------------------------------------------------------------------------
# Registry helpers
# --------------------------------------------------------------------------

function Get-RegistryValues {
    <#
        .SYNOPSIS
        Returns the values under a key as Name/Value pairs, minus PowerShell's
        own PS* noise properties. Returns nothing when the key is absent.
    #>
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) { return }
    $item = Get-ItemProperty -LiteralPath $Path -ErrorAction SilentlyContinue
    if (-not $item) { return }

    foreach ($property in $item.PSObject.Properties) {
        if ($property.Name -like 'PS*') { continue }
        [pscustomobject]@{
            Key   = $Path
            Name  = $property.Name
            Value = $property.Value
        }
    }
}

function Get-RegistryValue {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Name
    )

    if (-not (Test-Path -LiteralPath $Path)) { return $null }
    $item = Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction SilentlyContinue
    if (-not $item) { return $null }
    if (-not $item.PSObject.Properties[$Name]) { return $null }
    return $item.$Name
}

function Get-UserHivePaths {
    <#
        .SYNOPSIS
        Every loaded user hive, so per-user persistence is not missed just
        because the scan runs as a different account.
    #>
    $result = New-Object System.Collections.ArrayList

    $null = $result.Add([pscustomobject]@{ Sid = 'Current'; User = "$env:USERNAME"; Root = 'HKCU:' })

    if (-not (Get-PSDrive -Name HKU -ErrorAction SilentlyContinue)) {
        $null = New-PSDrive -Name HKU -PSProvider Registry -Root HKEY_USERS -Scope Script -ErrorAction SilentlyContinue
    }
    if (-not (Test-Path 'HKU:\')) { return $result }

    foreach ($hive in (Get-ChildItem 'HKU:\' -ErrorAction SilentlyContinue)) {
        $sid = Split-Path $hive.Name -Leaf
        # Skip machine/service SIDs and the _Classes shadow hives.
        if ($sid -notmatch '^S-1-5-21-[\d-]+$') { continue }
        $name = $sid
        try {
            $account = (New-Object Security.Principal.SecurityIdentifier($sid)).Translate([Security.Principal.NTAccount]).Value
            if ($account) { $name = $account }
        }
        catch { }
        $null = $result.Add([pscustomobject]@{ Sid = $sid; User = $name; Root = "HKU:\$sid" })
    }

    return $result
}

# --------------------------------------------------------------------------
# Path and signature forensics
# --------------------------------------------------------------------------

function Expand-PathVariables {
    param([string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $Path }
    $expanded = [Environment]::ExpandEnvironmentVariables($Path)
    # Native NT / systemroot prefixes seen in service ImagePath values.
    $expanded = $expanded -replace '^\\\?\?\\', ''
    $expanded = $expanded -replace '^\\SystemRoot\\', "$env:SystemRoot\"
    $expanded = $expanded -replace '^system32\\', "$env:SystemRoot\system32\"
    return $expanded.Trim()
}

function Get-ReferencedScriptContent {
    <#
        .SYNOPSIS
        Reads the content of a script file a command line points at.

        A Run key or Scheduled Task entry that reads
        "powershell.exe -File C:\ProgramData\Vendor\task.ps1" looks completely
        clean by command-line pattern matching alone - the badness, if any, is
        inside task.ps1, which nothing was reading before. This is capped at
        400 lines so one huge referenced file can't stall a scan.
    #>
    param([string]$CommandLine)

    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return $null }

    foreach ($match in [regex]::Matches($CommandLine, '(?i)(?<path>"[^"]+\.(ps1|vbs|js|jse|bat|cmd|wsf|hta)"|\S+\.(ps1|vbs|js|jse|bat|cmd|wsf|hta)\b)')) {
        $candidate = $match.Groups['path'].Value.Trim('"')
        $expanded  = Expand-PathVariables -Path $candidate
        if (-not (Test-Path -LiteralPath $expanded -PathType Leaf -ErrorAction SilentlyContinue)) { continue }

        try {
            $content = (Get-Content -LiteralPath $expanded -TotalCount 400 -ErrorAction Stop) -join "`n"
            if ($content) { return [pscustomobject]@{ Path = $expanded; Content = $content } }
        }
        catch { }
    }
    return $null
}

function Resolve-ExecutablePath {
    <#
        .SYNOPSIS
        Extracts the on-disk image from a command line.

        Handles quoted paths, unquoted paths containing spaces, bare command
        names on PATH, and rundll32/regsvr32 style invocations where the
        interesting file is an argument rather than the image.
    #>
    param([string]$CommandLine)

    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return $null }
    $line = Expand-PathVariables -Path $CommandLine.Trim()

    $candidate = $null

    if ($line.StartsWith('"')) {
        $end = $line.IndexOf('"', 1)
        if ($end -gt 1) { $candidate = $line.Substring(1, $end - 1) }
    }

    if (-not $candidate) {
        # Walk the unquoted string looking for the longest prefix that exists on
        # disk. "C:\Program Files\App\a.exe -x" must not resolve to "C:\Program".
        if ($line -match '^([a-zA-Z]:\\|\\\\)') {
            $parts = $line.Split(' ')
            for ($i = $parts.Count; $i -ge 1; $i--) {
                $probe = ($parts[0..($i - 1)] -join ' ').Trim()
                if ($probe -match '\.(exe|dll|sys|scr|com|bat|cmd|ps1|vbs|js|jar|msi)$' -or (Test-Path -LiteralPath $probe -PathType Leaf -ErrorAction SilentlyContinue)) {
                    $candidate = $probe
                    break
                }
            }
            if (-not $candidate) { $candidate = $parts[0] }
        }
        else {
            $candidate = $line.Split(' ')[0]
        }
    }

    if (-not $candidate) { return $null }
    $candidate = $candidate.Trim('"', ' ', "`t")

    # rundll32 / regsvr32 point at a DLL that matters more than the host binary.
    $leaf = try { Split-Path $candidate -Leaf } catch { $candidate }
    if ($leaf -match '^(rundll32|regsvr32)(\.exe)?$') {
        $remainder = $line.Substring([Math]::Min($line.Length, $line.IndexOf($leaf) + $leaf.Length)).Trim()
        $remainder = ($remainder -replace '^(/[a-zA-Z]\s+)+', '').Trim().Trim('"')
        if ($remainder) {
            $dll = $remainder.Split(',')[0].Split(' ')[0].Trim('"')
            $dll = Expand-PathVariables -Path $dll
            if ($dll -match '\.(dll|ocx|cpl)$') { $candidate = $dll }
        }
    }

    if ($candidate -notmatch '[\\/]') {
        $resolved = Get-Command $candidate -ErrorAction SilentlyContinue |
                    Where-Object { $_.Path } |
                    Select-Object -First 1
        if ($resolved) { $candidate = $resolved.Path }
    }

    return $candidate
}

function Get-SignatureInfo {
    <#
        .SYNOPSIS
        Authenticode verdict for a file, cached because the call is expensive
        and the same binaries recur across autorun locations.
    #>
    param([string]$Path)

    $empty = [pscustomobject]@{
        Path = $Path; Exists = $false; Status = 'NoFile'; Signer = ''
        IsSigned = $false; IsMicrosoft = $false; IsTrusted = $false
        Company = ''; Product = ''; VersionInfoOk = $false
    }

    if ([string]::IsNullOrWhiteSpace($Path)) { return $empty }
    $key = $Path.ToLowerInvariant()
    if ($script:SignatureCache.ContainsKey($key)) { return $script:SignatureCache[$key] }

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf -ErrorAction SilentlyContinue)) {
        $script:SignatureCache[$key] = $empty
        return $empty
    }

    $status = 'Unknown'; $signer = ''; $company = ''; $product = ''; $versionOk = $false
    try {
        $signature = Get-AuthenticodeSignature -LiteralPath $Path -ErrorAction Stop
        $status = "$($signature.Status)"
        if ($signature.SignerCertificate) { $signer = $signature.SignerCertificate.Subject }
    }
    catch { $status = 'Unreadable' }

    try {
        $info = (Get-Item -LiteralPath $Path -ErrorAction Stop).VersionInfo
        if ($info) {
            $company   = "$($info.CompanyName)".Trim()
            $product   = "$($info.ProductName)".Trim()
            $versionOk = -not [string]::IsNullOrWhiteSpace($company)
        }
    }
    catch { }

    # An exclusion list here is a trap: any SignatureStatus value the author
    # didn't think of (e.g. 'UnknownError', returned for a file that isn't a
    # valid PE at all - garbage bytes with an .exe extension) falls through
    # as "signed" by default. List the statuses that mean a signature was
    # actually present instead, so an unanticipated value defaults to unsigned.
    $isSigned  = $status -in @('Valid', 'HashMismatch', 'NotTrusted', 'Incompatible')
    $isTrusted = ($status -eq 'Valid')

    # Signer subject is authoritative; company name is only a hint because it is
    # trivially forged in an unsigned file's resources.
    $isMicrosoft = $false
    if ($isTrusted -and $signer -match 'O=Microsoft Corporation|CN=Microsoft (Windows|Corporation)') { $isMicrosoft = $true }

    $result = [pscustomobject]@{
        Path = $Path; Exists = $true; Status = $status; Signer = (Get-CommonName $signer)
        IsSigned = $isSigned; IsMicrosoft = $isMicrosoft; IsTrusted = $isTrusted
        Company = $company; Product = $product; VersionInfoOk = $versionOk
    }
    $script:SignatureCache[$key] = $result
    return $result
}

function Get-CommonName {
    <#
        .SYNOPSIS
        Pulls CN= out of an X.500 subject so reports stay readable.
    #>
    param([string]$Subject)

    if ([string]::IsNullOrWhiteSpace($Subject)) { return '' }
    if ($Subject -match 'CN=(?<cn>[^,]+)') { return $Matches['cn'].Trim('"', ' ') }
    return $Subject
}

function Test-SuspiciousPath {
    <#
        .SYNOPSIS
        Returns the reasons a path looks like a payload drop site, or nothing.
    #>
    param([string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return @() }
    $reasons = New-Object System.Collections.ArrayList

    foreach ($rule in $script:SuspiciousPathPatterns) {
        if ($Path -match $rule.Pattern) { $null = $reasons.Add($rule.Reason) }
    }

    $leaf = try { Split-Path $Path -Leaf } catch { $Path }

    # Right-to-left override and friends: used to disguise "xxxexe.doc" as a document.
    if ($leaf -match "[\u202A-\u202E\u2066-\u2069]") {
        $null = $reasons.Add('Filename contains a bidirectional text override character')
    }
    if ($leaf -match '\.(doc|docx|pdf|jpg|png|txt|xls|xlsx|mp4|zip)\s*\.(exe|scr|com|pif|bat|cmd|js|jse|vbs|vbe|wsf|hta|msi|scf|url|lnk)$') {
        $null = $reasons.Add('Filename uses a double extension')
    }
    if ($leaf -match '\s+\.(exe|scr|com|dll)$') {
        $null = $reasons.Add('Filename pads the extension with whitespace')
    }
    # System binary names living outside the system directory.
    if ($leaf -match '^(svchost|lsass|csrss|services|winlogon|explorer|smss|spoolsv|taskhost|taskhostw|dwm|conhost|wininit|lsm|sihost|ctfmon|dllhost|runtimebroker|searchindexer|fontdrvhost)\.exe$' -and
        $Path -notmatch '\\Windows\\(System32|SysWOW64|WinSxS)\\') {
        $null = $reasons.Add('Masquerades as a Windows system binary but sits outside System32')
    }

    return @($reasons)
}

function Test-SuspiciousCommand {
    <#
        .SYNOPSIS
        Matches a command line against known tradecraft patterns.
    #>
    param([string]$CommandLine)

    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return @() }
    $hits = New-Object System.Collections.ArrayList

    foreach ($rule in $script:SuspiciousCommandPatterns) {
        if ($CommandLine -match $rule.Pattern) {
            $null = $hits.Add([pscustomobject]@{ Reason = $rule.Reason; Severity = $rule.Severity })
        }
    }
    return @($hits)
}

function Get-WorstSeverity {
    <#
        .SYNOPSIS
        Highest severity in a set, defaulting when the set is empty.
    #>
    param([string[]]$Severities, [string]$Default = 'Info')

    $best = $Default
    foreach ($severity in $Severities) {
        if ([string]::IsNullOrWhiteSpace($severity)) { continue }
        if ($script:SeverityRank[$severity] -lt $script:SeverityRank[$best]) { $best = $severity }
    }
    return $best
}

function Test-UserWritable {
    <#
        .SYNOPSIS
        True when a non-administrator can modify the path.

        This is what turns "a service runs as SYSTEM" into "any user on this box
        can become SYSTEM", so it drives most of the privilege-path findings.
    #>
    param([string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
    $key = $Path.ToLowerInvariant()
    if ($script:AclCache.ContainsKey($key)) { return $script:AclCache[$key] }

    $result = $null
    try {
        if (-not (Test-Path -LiteralPath $Path -ErrorAction SilentlyContinue)) {
            $script:AclCache[$key] = $null
            return $null
        }

        $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
        $riskyIdentities = @(
            'Everyone','BUILTIN\Users','NT AUTHORITY\Authenticated Users',
            'NT AUTHORITY\INTERACTIVE','BUILTIN\Guests','NT AUTHORITY\ANONYMOUS LOGON'
        )
        $riskyRights = 'FullControl|Modify|Write|CreateFiles|WriteData|AppendData|ChangePermissions|TakeOwnership'

        $granting = New-Object System.Collections.ArrayList
        foreach ($ace in $acl.Access) {
            if ($ace.AccessControlType -ne 'Allow') { continue }
            $identity = "$($ace.IdentityReference)"
            if ($riskyIdentities -notcontains $identity) { continue }
            if ("$($ace.FileSystemRights)" -notmatch $riskyRights) { continue }
            $null = $granting.Add("$identity : $($ace.FileSystemRights)")
        }

        if ($granting.Count -gt 0) {
            $result = [pscustomobject]@{ Writable = $true;  Grants = @($granting); Owner = "$($acl.Owner)" }
        }
        else {
            $result = [pscustomobject]@{ Writable = $false; Grants = @();          Owner = "$($acl.Owner)" }
        }
    }
    catch { $result = $null }

    $script:AclCache[$key] = $result
    return $result
}

function Get-ProcessForPid {
    param([int]$ProcessId)

    if ($ProcessId -le 0) { return $null }
    try {
        $process = Get-Process -Id $ProcessId -ErrorAction Stop
        $path = $null
        try { $path = $process.Path } catch { }
        if (-not $path) {
            $wmi = Get-CimInstance Win32_Process -Filter "ProcessId=$ProcessId" -ErrorAction SilentlyContinue
            if ($wmi) { $path = $wmi.ExecutablePath }
        }
        return [pscustomobject]@{ Id = $ProcessId; Name = $process.ProcessName; Path = $path }
    }
    catch { return $null }
}

function ConvertTo-DisplayString {
    param([object]$Value, [int]$MaxLength = 400)

    if ($null -eq $Value) { return '' }
    if ($Value -is [array]) { $Value = ($Value | ForEach-Object { "$_" }) -join '; ' }
    $text = "$Value".Trim()
    if ($text.Length -gt $MaxLength) { $text = $text.Substring(0, $MaxLength) + ' ...(truncated)' }
    return $text
}

# ============================ lib/Checks.Persistence.ps1 ============================
<#
    Checks.Persistence.ps1 - Autoruns and persistence mechanisms.

    Defender scans files. It rarely objects to *where* a legitimate-looking
    binary has installed itself. This module walks the places code arranges to
    be re-executed and grades each entry on signature, location and command
    shape rather than on content.
#>

$script:PersistenceCategory = 'Persistence & Autoruns'

function Add-AutorunFinding {
    <#
        .SYNOPSIS
        Shared grading for "something will run this command later".

        Scores the resolved image (signature + location) and the command line
        (tradecraft patterns) and only emits a finding when something is off,
        so a clean machine produces a short report.
    #>
    param(
        [Parameter(Mandatory)][string]$Source,
        [Parameter(Mandatory)][string]$Name,
        [string]$CommandLine,
        [string]$Check,
        [string]$BaselineSeverity = 'Low',
        [hashtable]$ExtraEvidence,
        [switch]$AlwaysReport
    )

    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return }

    $imagePath = Resolve-ExecutablePath -CommandLine $CommandLine
    $signature = Get-SignatureInfo -Path $imagePath
    $pathFlags = @(Test-SuspiciousPath -Path $imagePath)
    $cmdFlags  = @(Test-SuspiciousCommand -CommandLine $CommandLine)

    # The command line itself can look completely clean while pointing at a
    # script file whose actual content is the malicious part - inspect that
    # referenced file too, not just the invocation that names it.
    $scriptContentFlags = @()
    $referencedScript = Get-ReferencedScriptContent -CommandLine $CommandLine
    if ($referencedScript) {
        $scriptContentFlags = @(Test-SuspiciousCommand -CommandLine $referencedScript.Content)
    }

    $reasons    = New-Object System.Collections.ArrayList
    $severities = New-Object System.Collections.ArrayList

    foreach ($reason in $pathFlags) {
        $null = $reasons.Add($reason)
        $null = $severities.Add('High')
    }
    foreach ($hit in $cmdFlags) {
        $null = $reasons.Add($hit.Reason)
        $null = $severities.Add($hit.Severity)
    }
    foreach ($hit in $scriptContentFlags) {
        $null = $reasons.Add("Referenced script $(Split-Path $referencedScript.Path -Leaf): $($hit.Reason)")
        $null = $severities.Add($hit.Severity)
    }

    if ($imagePath -and -not $signature.Exists) {
        $null = $reasons.Add('Target file does not exist on disk (stale or removed payload)')
        $null = $severities.Add('Medium')
    }
    elseif ($signature.Exists -and -not $signature.IsMicrosoft) {
        if (-not $signature.IsSigned) {
            $null = $reasons.Add('Binary is not digitally signed')
            $null = $severities.Add('Medium')
        }
        elseif (-not $signature.IsTrusted) {
            $null = $reasons.Add("Signature does not validate (status: $($signature.Status))")
            $null = $severities.Add('High')
        }
    }

    $leaf = if ($imagePath) { try { Split-Path $imagePath -Leaf } catch { '' } } else { '' }
    $isLolBin = [bool]($leaf -and $script:LolBinNames -contains $leaf.ToLowerInvariant())
    if ($isLolBin) {
        $null = $reasons.Add("Persistence runs through $leaf, a signed Windows binary commonly abused to proxy execution")
        $null = $severities.Add('Medium')
    }

    if ($reasons.Count -eq 0 -and -not $AlwaysReport) { return }

    $severity = Get-WorstSeverity -Severities @($severities) -Default $BaselineSeverity

    # A trusted Microsoft binary in a normal location is background noise even
    # when it trips a soft heuristic - but not when the binary itself is a
    # known execution-proxy tool, or the script it was told to run is bad;
    # neither of those signals may be silently dropped.
    if ($signature.IsMicrosoft -and $pathFlags.Count -eq 0 -and $cmdFlags.Count -eq 0 -and $scriptContentFlags.Count -eq 0 -and -not $isLolBin) { $severity = 'Info' }

    $evidence = [ordered]@{
        'Location'    = $Source
        'Entry name'  = $Name
        'Command'     = ConvertTo-DisplayString $CommandLine 600
        'Resolved image' = $imagePath
        'Signature'   = if ($signature.Exists) { "$($signature.Status)$(if ($signature.Signer) { " - $($signature.Signer)" })" } else { 'file not found' }
        'Publisher'   = $signature.Company
    }
    if ($referencedScript) { $evidence['Referenced script'] = $referencedScript.Path }
    if ($ExtraEvidence) {
        foreach ($key in $ExtraEvidence.Keys) { $evidence[$key] = ConvertTo-DisplayString $ExtraEvidence[$key] }
    }

    Add-Finding -Category $script:PersistenceCategory `
                -Check $Check `
                -Severity $severity `
                -Title "Autorun entry '$Name' in $Source" `
                -Detail ($reasons -join '; ') `
                -Recommendation "Confirm you installed this. If unrecognised, remove the entry and quarantine the target file before rebooting." `
                -Evidence $evidence
}

# --------------------------------------------------------------------------

function Test-RunKeys {
    Write-ScanLog -Message 'Run / RunOnce registry keys' -Level 'Step'

    $machineKeys = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnceEx'
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunServices'
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunServicesOnce'
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Run'
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\RunOnce'
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run'
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run'
    )
    $userKeySuffixes = @(
        'SOFTWARE\Microsoft\Windows\CurrentVersion\Run'
        'SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
        'SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnceEx'
        'SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run'
    )

    foreach ($key in $machineKeys) {
        foreach ($value in (Get-RegistryValues -Path $key)) {
            Add-AutorunFinding -Source ($key -replace '^HKLM:', 'HKLM') -Name $value.Name `
                               -CommandLine ([string]$value.Value) -Check 'RunKeys'
        }
    }

    foreach ($hive in (Get-UserHivePaths)) {
        foreach ($suffix in $userKeySuffixes) {
            $key = Join-Path $hive.Root $suffix
            foreach ($value in (Get-RegistryValues -Path $key)) {
                Add-AutorunFinding -Source "$($hive.User) : $suffix" -Name $value.Name `
                                   -CommandLine ([string]$value.Value) -Check 'RunKeys'
            }
        }
    }
}

function Test-StartupFolders {
    Write-ScanLog -Message 'Startup folders' -Level 'Step'

    $folders = New-Object System.Collections.ArrayList
    $null = $folders.Add("$env:ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp")
    foreach ($profileDir in (Get-ChildItem "$env:SystemDrive\Users" -Directory -ErrorAction SilentlyContinue)) {
        $null = $folders.Add((Join-Path $profileDir.FullName 'AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup'))
    }

    foreach ($folder in $folders) {
        if (-not (Test-Path -LiteralPath $folder)) { continue }
        foreach ($file in (Get-ChildItem -LiteralPath $folder -File -Force -ErrorAction SilentlyContinue)) {
            if ($file.Name -eq 'desktop.ini') { continue }

            $target = $file.FullName
            $note   = $null

            # Resolve .lnk so the shortcut's target gets graded, not the shortcut.
            if ($file.Extension -eq '.lnk') {
                try {
                    $shell    = New-Object -ComObject WScript.Shell
                    $shortcut = $shell.CreateShortcut($file.FullName)
                    if ($shortcut.TargetPath) {
                        $note   = "Shortcut -> $($shortcut.TargetPath) $($shortcut.Arguments)"
                        $target = "$($shortcut.TargetPath) $($shortcut.Arguments)"
                    }
                    [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shell)
                }
                catch { }
            }

            Add-AutorunFinding -Source ($folder -replace [regex]::Escape($env:SystemDrive), '') `
                               -Name $file.Name -CommandLine $target -Check 'StartupFolder' `
                               -ExtraEvidence @{ 'Shortcut target' = $note; 'Created' = $file.CreationTime }
        }
    }
}

function Test-ScheduledTasks {
    Write-ScanLog -Message 'Scheduled tasks' -Level 'Step'

    $tasks = $null
    try { $tasks = Get-ScheduledTask -ErrorAction Stop } catch { }

    if (-not $tasks) {
        Write-ScanLog -Message 'Get-ScheduledTask unavailable; scheduled task persistence could not be checked' -Level 'Warn'
        return
    }

    foreach ($task in $tasks) {
        # Microsoft's own tasks under \Microsoft\Windows\ are enormous in number
        # and uniformly benign; only inspect them if the action looks wrong.
        $isMicrosoftPath = $task.TaskPath -like '\Microsoft\Windows\*'

        foreach ($action in @($task.Actions)) {
            if (-not $action.PSObject.Properties['Execute']) { continue }
            $execute = "$($action.Execute)"
            if ([string]::IsNullOrWhiteSpace($execute)) { continue }

            $arguments = ''
            if ($action.PSObject.Properties['Arguments']) { $arguments = "$($action.Arguments)" }
            $commandLine = "$execute $arguments".Trim()

            $principal = ''
            $runLevel  = ''
            try {
                $principal = "$($task.Principal.UserId)"
                $runLevel  = "$($task.Principal.RunLevel)"
            }
            catch { }

            $extra = @{
                'Task path'  = $task.TaskPath
                'Runs as'    = "$principal $(if ($runLevel -eq 'Highest') { '(elevated)' })".Trim()
                'State'      = "$($task.State)"
                'Author'     = "$($task.Author)"
            }

            if ($isMicrosoftPath) {
                # Still grade it, but require a hard signal before reporting.
                $flags = @(Test-SuspiciousCommand -CommandLine $commandLine) + @(Test-SuspiciousPath -Path (Resolve-ExecutablePath $commandLine))
                if ($flags.Count -eq 0) { continue }
                $extra['Note'] = 'Task lives in the Microsoft task tree but its action is unusual - possible hijack of a built-in task'
            }

            Add-AutorunFinding -Source "Scheduled Task $($task.TaskPath)$($task.TaskName)" `
                               -Name $task.TaskName -CommandLine $commandLine `
                               -Check 'ScheduledTasks' -ExtraEvidence $extra
        }
    }

    # Tasks that hide themselves from the Task Scheduler UI.
    foreach ($task in $tasks) {
        $hidden = $false
        try { $hidden = [bool]$task.Settings.Hidden } catch { }
        if (-not $hidden) { continue }
        if ($task.TaskPath -like '\Microsoft\*') { continue }

        Add-Finding -Category $script:PersistenceCategory -Check 'ScheduledTasks' -Severity 'Medium' `
                    -Title "Hidden scheduled task '$($task.TaskName)'" `
                    -Detail 'The task sets the Hidden flag, so it does not appear in Task Scheduler by default. Legitimate third-party software rarely needs this.' `
                    -Recommendation 'Inspect the task action. Remove it if you do not recognise the software that created it.' `
                    -Evidence ([ordered]@{
                        'Task path' = "$($task.TaskPath)$($task.TaskName)"
                        'Author'    = "$($task.Author)"
                        'State'     = "$($task.State)"
                    })
    }
}

function Test-Services {
    Write-ScanLog -Message 'Services' -Level 'Step'

    $services = $null
    try { $services = Get-CimInstance Win32_Service -ErrorAction Stop } catch { return }

    foreach ($service in $services) {
        $imagePath = "$($service.PathName)"
        if ([string]::IsNullOrWhiteSpace($imagePath)) { continue }

        $resolved  = Resolve-ExecutablePath -CommandLine $imagePath
        $signature = Get-SignatureInfo -Path $resolved
        if ($signature.IsMicrosoft -and (Test-SuspiciousPath -Path $resolved).Count -eq 0) { continue }

        $extra = @{
            'Service name'  = $service.Name
            'Display name'  = $service.DisplayName
            'Start mode'    = $service.StartMode
            'State'         = $service.State
            'Runs as'       = $service.StartName
        }

        Add-AutorunFinding -Source "Service: $($service.Name)" -Name $service.DisplayName `
                           -CommandLine $imagePath -Check 'Services' -ExtraEvidence $extra
    }

    # svchost-hosted services load a DLL named in the registry rather than an
    # image path, so they are invisible to the loop above.
    foreach ($service in $services) {
        $key = "HKLM:\SYSTEM\CurrentControlSet\Services\$($service.Name)\Parameters"
        $dll = Get-RegistryValue -Path $key -Name 'ServiceDll'
        if (-not $dll) { continue }

        $dllPath   = Expand-PathVariables -Path ([string]$dll)
        $signature = Get-SignatureInfo -Path $dllPath
        if ($signature.IsMicrosoft) { continue }

        $reasons = @(Test-SuspiciousPath -Path $dllPath)
        if (-not $signature.Exists)      { $reasons += 'ServiceDll target is missing from disk' }
        elseif (-not $signature.IsSigned) { $reasons += 'ServiceDll is unsigned' }
        elseif (-not $signature.IsTrusted) { $reasons += "ServiceDll signature is invalid ($($signature.Status))" }
        if ($reasons.Count -eq 0) { continue }

        Add-Finding -Category $script:PersistenceCategory -Check 'Services' -Severity 'High' `
                    -Title "Service '$($service.Name)' loads a non-Microsoft DLL into svchost" `
                    -Detail ($reasons -join '; ') `
                    -Recommendation 'Service DLL hijacking is a common persistence route. Verify the DLL publisher; if unknown, stop the service and quarantine the file.' `
                    -Evidence ([ordered]@{
                        'Service'    = "$($service.Name) ($($service.DisplayName))"
                        'ServiceDll' = $dllPath
                        'Signature'  = "$($signature.Status) $($signature.Signer)"
                        'Start mode' = $service.StartMode
                    })
    }
}

function Test-WmiSubscriptions {
    <#
        .SYNOPSIS
        WMI event subscriptions - filesystem-free persistence that Defender's
        file scanning cannot see at all, since the payload lives in the CIM
        repository rather than on disk.
    #>
    Write-ScanLog -Message 'WMI event subscriptions' -Level 'Step'

    $consumers = @()
    $filters   = @()
    $bindings  = @()
    try {
        $consumers = @(Get-CimInstance -Namespace 'root\subscription' -ClassName '__EventConsumer' -ErrorAction Stop)
        $filters   = @(Get-CimInstance -Namespace 'root\subscription' -ClassName '__EventFilter' -ErrorAction SilentlyContinue)
        $bindings  = @(Get-CimInstance -Namespace 'root\subscription' -ClassName '__FilterToConsumerBinding' -ErrorAction SilentlyContinue)
    }
    catch {
        Write-ScanLog -Message 'root\subscription is not readable (needs an elevated session)' -Level 'Warn'
        return
    }

    foreach ($consumer in $consumers) {
        $class = $consumer.CimClass.CimClassName
        $name  = "$($consumer.Name)"

        # Shipped with Windows / SCCM and present on clean machines.
        if ($name -match '^(SCM Event Log Consumer|BVTConsumer|TSLogonEvents)$') { continue }

        $payload = ''
        $type    = $class
        if ($class -eq 'CommandLineEventConsumer') {
            $payload = "$($consumer.CommandLineTemplate)"
            if ($consumer.ExecutablePath) { $payload = "$($consumer.ExecutablePath) $payload" }
        }
        elseif ($class -eq 'ActiveScriptEventConsumer') {
            $payload = "$($consumer.ScriptText)"
            if ($consumer.ScriptFileName) { $payload = "$($consumer.ScriptFileName) $payload" }
            $type = "ActiveScriptEventConsumer ($($consumer.ScriptingEngine))"
        }
        else {
            $payload = "$($consumer.Name)"
        }

        $linkedFilter = ''
        foreach ($binding in $bindings) {
            $consumerName = $null
            if ("$($binding.Consumer)" -match '="(?<n>[^"]*)"\s*$') { $consumerName = $Matches['n'] }
            if ($consumerName -ne $name) { continue }

            foreach ($filter in $filters) {
                $filterName = $null
                if ("$($binding.Filter)" -match '="(?<n>[^"]*)"\s*$') { $filterName = $Matches['n'] }
                if ($filterName -eq $filter.Name) { $linkedFilter = "$($filter.Query)" }
            }
        }

        $severity = if ($class -in @('CommandLineEventConsumer', 'ActiveScriptEventConsumer')) { 'Critical' } else { 'High' }
        $flags    = @(Test-SuspiciousCommand -CommandLine $payload)
        $detail   = 'A WMI event consumer runs code when a system event fires. This persists across reboots, leaves no autorun registry entry, and is a well-known technique for staying resident.'
        if ($flags.Count -gt 0) { $detail += ' Command shape flags: ' + (($flags | ForEach-Object { $_.Reason }) -join '; ') + '.' }

        Add-Finding -Category $script:PersistenceCategory -Check 'WmiSubscriptions' -Severity $severity `
                    -Title "WMI event consumer '$name'" `
                    -Detail $detail `
                    -Recommendation "Unless you or your IT department deployed this, treat it as malicious. Remove with: Get-CimInstance -Namespace root\subscription -ClassName $class | Where-Object Name -eq '$name' | Remove-CimInstance (also remove the paired __EventFilter and __FilterToConsumerBinding)." `
                    -Evidence ([ordered]@{
                        'Consumer type' = $type
                        'Name'          = $name
                        'Payload'       = ConvertTo-DisplayString $payload 800
                        'Trigger query' = ConvertTo-DisplayString $linkedFilter 500
                    })
    }
}

function Test-ImageFileExecutionOptions {
    Write-ScanLog -Message 'Image File Execution Options and SilentProcessExit' -Level 'Step'

    $roots = @(
        'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options'
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows NT\CurrentVersion\Image File Execution Options'
    )

    foreach ($root in $roots) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($entry in (Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue)) {
            $debugger = Get-RegistryValue -Path $entry.PSPath -Name 'Debugger'
            if ($debugger) {
                Add-Finding -Category $script:PersistenceCategory -Check 'IFEO' -Severity 'Critical' `
                            -Title "IFEO debugger hijack on $($entry.PSChildName)" `
                            -Detail "Launching $($entry.PSChildName) will instead start '$debugger'. This both persists code and can be used to neutralise a security tool by pointing its executable at something harmless." `
                            -Recommendation "Delete the Debugger value under $($entry.Name) unless a developer intentionally configured this for debugging." `
                            -Evidence ([ordered]@{
                                'Hijacked image' = $entry.PSChildName
                                'Debugger'       = ConvertTo-DisplayString $debugger
                                'Key'            = $entry.Name
                            })
            }

            $globalFlag = Get-RegistryValue -Path $entry.PSPath -Name 'GlobalFlag'
            if ($globalFlag -and ([int]$globalFlag -band 0x200)) {
                $silentKey = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SilentProcessExit\$($entry.PSChildName)"
                $monitor   = Get-RegistryValue -Path $silentKey -Name 'MonitorProcess'
                if ($monitor) {
                    Add-Finding -Category $script:PersistenceCategory -Check 'IFEO' -Severity 'Critical' `
                                -Title "SilentProcessExit persistence on $($entry.PSChildName)" `
                                -Detail "When $($entry.PSChildName) exits, Windows will launch '$monitor'. This is a stealthy trigger that survives reboot and is not shown by most autorun viewers." `
                                -Recommendation "Remove the MonitorProcess value under $silentKey and clear the GlobalFlag under the IFEO key." `
                                -Evidence ([ordered]@{
                                    'Monitored image' = $entry.PSChildName
                                    'MonitorProcess'  = ConvertTo-DisplayString $monitor
                                    'GlobalFlag'      = $globalFlag
                                })
                }
            }
        }
    }
}

function Test-WinlogonAndAppInit {
    Write-ScanLog -Message 'Winlogon, AppInit and LSA extension points' -Level 'Step'

    $winlogonKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
    $expected = @{
        'Shell'    = 'explorer.exe'
        'Userinit' = "$env:SystemRoot\system32\userinit.exe,"
        'Taskman'  = $null
    }

    foreach ($name in $expected.Keys) {
        $value = Get-RegistryValue -Path $winlogonKey -Name $name
        if (-not $value) { continue }

        $normalized = "$value".Trim().TrimEnd(',').ToLowerInvariant()
        $baseline   = if ($expected[$name]) { "$($expected[$name])".Trim().TrimEnd(',').ToLowerInvariant() } else { $null }

        if ($name -eq 'Taskman' -or ($baseline -and $normalized -ne $baseline)) {
            Add-Finding -Category $script:PersistenceCategory -Check 'Winlogon' -Severity 'Critical' `
                        -Title "Winlogon $name has been modified" `
                        -Detail "Winlogon's $name value runs at every interactive logon before the desktop appears. Expected '$($expected[$name])', found '$value'." `
                        -Recommendation "Restore the default value. If $name is 'Shell', the default is explorer.exe; for 'Userinit' it is $env:SystemRoot\system32\userinit.exe, (trailing comma included). 'Taskman' should not normally exist." `
                        -Evidence ([ordered]@{
                            'Value name' = $name
                            'Current'    = ConvertTo-DisplayString $value
                            'Expected'   = if ($expected[$name]) { $expected[$name] } else { '(value should be absent)' }
                        })
        }
    }

    foreach ($subKey in @('Notify')) {
        $path = Join-Path $winlogonKey $subKey
        if (-not (Test-Path -LiteralPath $path)) { continue }
        foreach ($entry in (Get-ChildItem -LiteralPath $path -ErrorAction SilentlyContinue)) {
            $dll = Get-RegistryValue -Path $entry.PSPath -Name 'DLLName'
            if (-not $dll) { continue }
            Add-AutorunFinding -Source "Winlogon\Notify\$($entry.PSChildName)" -Name $entry.PSChildName `
                               -CommandLine ([string]$dll) -Check 'Winlogon' -BaselineSeverity 'High' -AlwaysReport
        }
    }

    # AppInit_DLLs is loaded into every process that links user32.dll.
    foreach ($key in @(
        'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows'
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows NT\CurrentVersion\Windows'
    )) {
        $appInit = Get-RegistryValue -Path $key -Name 'AppInit_DLLs'
        if ([string]::IsNullOrWhiteSpace("$appInit")) { continue }
        $enabled = Get-RegistryValue -Path $key -Name 'LoadAppInit_DLLs'

        Add-Finding -Category $script:PersistenceCategory -Check 'AppInit' -Severity 'Critical' `
                    -Title 'AppInit_DLLs is populated' `
                    -Detail "AppInit_DLLs injects the listed DLLs into essentially every GUI process on the system. It is deprecated and almost never used legitimately on a modern machine. Enabled flag: $enabled." `
                    -Recommendation 'Clear the AppInit_DLLs value and set LoadAppInit_DLLs to 0.' `
                    -Evidence ([ordered]@{ 'Key' = $key; 'AppInit_DLLs' = ConvertTo-DisplayString $appInit; 'LoadAppInit_DLLs' = $enabled })
    }

    $appCert = Get-RegistryValues -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\AppCertDlls'
    foreach ($value in $appCert) {
        Add-Finding -Category $script:PersistenceCategory -Check 'AppCertDlls' -Severity 'Critical' `
                    -Title "AppCertDlls entry '$($value.Name)'" `
                    -Detail 'AppCertDlls load into any process that calls CreateProcess. The key is empty on a clean Windows install.' `
                    -Recommendation 'Delete this value unless you can attribute it to installed software.' `
                    -Evidence ([ordered]@{ 'Name' = $value.Name; 'DLL' = ConvertTo-DisplayString $value.Value })
    }

    # LSA packages run inside lsass.exe - the process holding credentials.
    $lsaKey = 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa'
    $lsaChecks = @{
        'Security Packages'       = @('kerberos','msv1_0','schannel','wdigest','tspkg','pku2u','negoexts','cloudap','""')
        'Authentication Packages' = @('msv1_0','relogonms')
        'Notification Packages'   = @('scecli','rassfm','kdcsvc')
    }
    foreach ($name in $lsaChecks.Keys) {
        $value = Get-RegistryValue -Path $lsaKey -Name $name
        if (-not $value) { continue }
        foreach ($package in @($value)) {
            $clean = "$package".Trim().Trim('"').ToLowerInvariant()
            if ([string]::IsNullOrWhiteSpace($clean)) { continue }
            if ($lsaChecks[$name] -contains $clean) { continue }

            Add-Finding -Category $script:PersistenceCategory -Check 'LsaPackages' -Severity 'Critical' `
                        -Title "Unrecognised LSA package '$package' in $name" `
                        -Detail 'LSA packages are DLLs loaded into lsass.exe, the process that holds credential material. An unexpected entry here is a classic credential-theft implant and is not something Defender flags by default.' `
                        -Recommendation "Identify $package in $env:SystemRoot\system32. If you cannot attribute it to installed security software, treat the machine as compromised and rotate credentials from a clean device." `
                        -Evidence ([ordered]@{ 'Registry value' = $name; 'Package' = "$package"; 'Key' = $lsaKey })
        }
    }
}

function Test-ComHijacks {
    <#
        .SYNOPSIS
        Per-user COM registrations that shadow machine-wide ones.

        HKCU\Software\Classes wins over HKLM for the calling user, so writing a
        CLSID there redirects a system component into an attacker DLL without
        needing administrator rights.
    #>
    Write-ScanLog -Message 'COM object hijacks (HKCU shadowing HKLM)' -Level 'Step'

    foreach ($hive in (Get-UserHivePaths)) {
        $clsidRoot = Join-Path $hive.Root 'SOFTWARE\Classes\CLSID'
        if (-not (Test-Path -LiteralPath $clsidRoot)) { continue }

        foreach ($clsid in (Get-ChildItem -LiteralPath $clsidRoot -ErrorAction SilentlyContinue)) {
            foreach ($serverType in @('InprocServer32', 'LocalServer32', 'InprocServer')) {
                $serverKey = Join-Path $clsid.PSPath $serverType
                if (-not (Test-Path -LiteralPath $serverKey)) { continue }

                $default = Get-RegistryValue -Path $serverKey -Name '(default)'
                if ([string]::IsNullOrWhiteSpace("$default")) { continue }

                $shadowsMachine = Test-Path -LiteralPath "HKLM:\SOFTWARE\Classes\CLSID\$($clsid.PSChildName)\$serverType"
                $severity = if ($shadowsMachine) { 'Critical' } else { 'High' }
                $detail = if ($shadowsMachine) {
                    "This per-user CLSID registration overrides a machine-wide one. Any process running as this user that instantiates $($clsid.PSChildName) will load the user-controlled file instead of the system component."
                } else {
                    "A per-user COM server is registered for $($clsid.PSChildName). Per-user COM registration is uncommon outside of a handful of applications."
                }

                Add-AutorunFinding -Source "$($hive.User) COM $serverType $($clsid.PSChildName)" `
                                   -Name $clsid.PSChildName -CommandLine ([string]$default) `
                                   -Check 'ComHijack' -BaselineSeverity $severity -AlwaysReport `
                                   -ExtraEvidence @{
                                       'CLSID'                = $clsid.PSChildName
                                       'Shadows HKLM'         = $shadowsMachine
                                       'Why this matters'     = $detail
                                   }
            }
        }
    }
}

function Test-PowerShellProfiles {
    Write-ScanLog -Message 'PowerShell profile scripts' -Level 'Step'

    $profilePaths = New-Object System.Collections.ArrayList
    foreach ($name in @('AllUsersAllHosts','AllUsersCurrentHost','CurrentUserAllHosts','CurrentUserCurrentHost')) {
        try {
            $path = $PROFILE.$name
            if ($path) { $null = $profilePaths.Add([pscustomobject]@{ Scope = $name; Path = $path }) }
        }
        catch { }
    }
    foreach ($profileDir in (Get-ChildItem "$env:SystemDrive\Users" -Directory -ErrorAction SilentlyContinue)) {
        foreach ($relative in @('Documents\WindowsPowerShell\profile.ps1','Documents\WindowsPowerShell\Microsoft.PowerShell_profile.ps1','Documents\PowerShell\profile.ps1')) {
            $null = $profilePaths.Add([pscustomobject]@{ Scope = "User: $($profileDir.Name)"; Path = (Join-Path $profileDir.FullName $relative) })
        }
    }

    $seen = @{}
    foreach ($entry in $profilePaths) {
        if (-not $entry.Path) { continue }
        $key = $entry.Path.ToLowerInvariant()
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        if (-not (Test-Path -LiteralPath $entry.Path -PathType Leaf)) { continue }

        $content = ''
        try { $content = (Get-Content -LiteralPath $entry.Path -Raw -ErrorAction Stop) } catch { }
        $flags = @(Test-SuspiciousCommand -CommandLine $content)

        $severity = if ($flags.Count -gt 0) { Get-WorstSeverity -Severities @($flags | ForEach-Object { $_.Severity }) -Default 'High' } else { 'Low' }
        $detail = 'A PowerShell profile executes automatically in every PowerShell session. It is a quiet persistence and credential-capture location.'
        if ($flags.Count -gt 0) { $detail += ' Flags: ' + (($flags | ForEach-Object { $_.Reason }) -join '; ') + '.' }

        Add-Finding -Category $script:PersistenceCategory -Check 'PowerShellProfile' -Severity $severity `
                    -Title "PowerShell profile present ($($entry.Scope))" `
                    -Detail $detail `
                    -Recommendation 'Open the file and confirm every line is yours. Profiles you did not create should be removed.' `
                    -Evidence ([ordered]@{
                        'Path'     = $entry.Path
                        'Modified' = (Get-Item -LiteralPath $entry.Path -ErrorAction SilentlyContinue).LastWriteTime
                        'Preview'  = ConvertTo-DisplayString $content 600
                    })
    }
}

function Test-ExplorerExtensionPoints {
    Write-ScanLog -Message 'Explorer and shell extension points' -Level 'Step'

    # Browser Helper Objects still load into anything hosting the IE control.
    foreach ($bhoRoot in @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\Browser Helper Objects'
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Explorer\Browser Helper Objects'
    )) {
        if (-not (Test-Path -LiteralPath $bhoRoot)) { continue }
        foreach ($bho in (Get-ChildItem -LiteralPath $bhoRoot -ErrorAction SilentlyContinue)) {
            $clsid  = $bho.PSChildName
            $server = Get-RegistryValue -Path "HKLM:\SOFTWARE\Classes\CLSID\$clsid\InprocServer32" -Name '(default)'
            Add-AutorunFinding -Source 'Browser Helper Object' -Name $clsid `
                               -CommandLine ([string]$server) -Check 'ShellExtensions' `
                               -BaselineSeverity 'Medium' -AlwaysReport -ExtraEvidence @{ 'CLSID' = $clsid }
        }
    }

    # ShellServiceObjectDelayLoad entries load into explorer.exe at logon.
    $ssodl = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\ShellServiceObjectDelayLoad'
    foreach ($value in (Get-RegistryValues -Path $ssodl)) {
        $server = Get-RegistryValue -Path "HKLM:\SOFTWARE\Classes\CLSID\$($value.Value)\InprocServer32" -Name '(default)'
        if (-not $server) { continue }
        Add-AutorunFinding -Source 'ShellServiceObjectDelayLoad' -Name $value.Name `
                           -CommandLine ([string]$server) -Check 'ShellExtensions' -ExtraEvidence @{ 'CLSID' = $value.Value }
    }

    # Active Setup runs StubPath once per user at first logon.
    foreach ($activeSetupRoot in @(
        'HKLM:\SOFTWARE\Microsoft\Active Setup\Installed Components'
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Active Setup\Installed Components'
    )) {
        if (-not (Test-Path -LiteralPath $activeSetupRoot)) { continue }
        foreach ($component in (Get-ChildItem -LiteralPath $activeSetupRoot -ErrorAction SilentlyContinue)) {
            $stub = Get-RegistryValue -Path $component.PSPath -Name 'StubPath'
            if ([string]::IsNullOrWhiteSpace("$stub")) { continue }
            Add-AutorunFinding -Source 'Active Setup StubPath' -Name $component.PSChildName `
                               -CommandLine ([string]$stub) -Check 'ActiveSetup' `
                               -ExtraEvidence @{ 'Component' = (Get-RegistryValue -Path $component.PSPath -Name '(default)') }
        }
    }

    # File association hijack: what actually runs when you double-click an .exe.
    $exeCommand = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Classes\exefile\shell\open\command' -Name '(default)'
    if ($exeCommand -and "$exeCommand".Trim() -ne '"%1" %*') {
        Add-Finding -Category $script:PersistenceCategory -Check 'FileAssociation' -Severity 'Critical' `
                    -Title 'Executable file association has been hijacked' `
                    -Detail "Running any .exe passes through '$exeCommand' instead of the default '`"%1`" %*'. Every program you launch would be proxied through the attacker's command." `
                    -Recommendation 'Restore HKLM\SOFTWARE\Classes\exefile\shell\open\command to "%1" %*' `
                    -Evidence ([ordered]@{ 'Current' = ConvertTo-DisplayString $exeCommand; 'Expected' = '"%1" %*' })
    }

    # Screensaver executable is a long-standing autorun.
    foreach ($hive in (Get-UserHivePaths)) {
        $screensaver = Get-RegistryValue -Path (Join-Path $hive.Root 'Control Panel\Desktop') -Name 'SCRNSAVE.EXE'
        if ([string]::IsNullOrWhiteSpace("$screensaver")) { continue }
        if ("$screensaver" -match '\.scr$' -and "$screensaver" -match '\\Windows\\(System32|SysWOW64)\\') { continue }
        Add-AutorunFinding -Source "$($hive.User) screensaver" -Name 'SCRNSAVE.EXE' `
                           -CommandLine ([string]$screensaver) -Check 'Screensaver' -BaselineSeverity 'Medium' -AlwaysReport
    }
}

function Test-BootAndDriverPersistence {
    Write-ScanLog -Message 'Boot execution and kernel drivers' -Level 'Step'

    $bootExecute = Get-RegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name 'BootExecute'
    foreach ($entry in @($bootExecute)) {
        $text = "$entry".Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        if ($text -match '^autocheck autochk') { continue }

        Add-Finding -Category $script:PersistenceCategory -Check 'BootExecute' -Severity 'Critical' `
                    -Title "Non-default BootExecute entry" `
                    -Detail "BootExecute runs native applications before Win32 and before any security product loads. The only expected entries are autocheck autochk variants; found '$text'." `
                    -Recommendation 'Remove the entry unless a disk utility you installed documented it.' `
                    -Evidence ([ordered]@{ 'Entry' = $text })
    }

    # Unsigned or invalidly signed kernel drivers - full ring 0, and a running
    # driver can hide itself from user-mode scanners entirely.
    $drivers = $null
    try { $drivers = Get-CimInstance Win32_SystemDriver -ErrorAction Stop } catch { return }

    foreach ($driver in $drivers) {
        $path = Expand-PathVariables -Path "$($driver.PathName)"
        if ([string]::IsNullOrWhiteSpace($path)) { continue }

        $signature = Get-SignatureInfo -Path $path
        if ($signature.IsMicrosoft) { continue }
        if ($signature.IsTrusted -and $driver.State -ne 'Running') { continue }

        $reasons = @(Test-SuspiciousPath -Path $path)
        if (-not $signature.Exists)        { $reasons += 'Driver file is missing from disk' }
        elseif (-not $signature.IsSigned)  { $reasons += 'Driver is unsigned' }
        elseif (-not $signature.IsTrusted) { $reasons += "Driver signature does not validate ($($signature.Status))" }
        if ($reasons.Count -eq 0) { continue }

        Add-Finding -Category $script:PersistenceCategory -Check 'Drivers' -Severity 'Critical' `
                    -Title "Kernel driver '$($driver.Name)' is not properly signed" `
                    -Detail (($reasons -join '; ') + ". A driver runs in kernel mode and can conceal files, processes and network connections from every user-mode scanner, including Defender.") `
                    -Recommendation 'Identify the driver publisher. Unattributable kernel drivers warrant offline analysis and, if confirmed malicious, a rebuild of the machine.' `
                    -Evidence ([ordered]@{
                        'Driver'     = "$($driver.Name) ($($driver.DisplayName))"
                        'Path'       = $path
                        'State'      = $driver.State
                        'Start mode' = $driver.StartMode
                        'Signature'  = "$($signature.Status) $($signature.Signer)"
                    })
    }
}

function Test-NetshAndPrintPersistence {
    Write-ScanLog -Message 'netsh helpers, print monitors and Winsock providers' -Level 'Step'

    foreach ($value in (Get-RegistryValues -Path 'HKLM:\SOFTWARE\Microsoft\NetSh')) {
        $dll = Expand-PathVariables -Path ([string]$value.Value)
        if ($dll -notmatch '[\\/]') { $dll = Join-Path "$env:SystemRoot\System32" $dll }
        $signature = Get-SignatureInfo -Path $dll
        if ($signature.IsMicrosoft) { continue }

        Add-AutorunFinding -Source 'netsh helper DLL' -Name $value.Name -CommandLine $dll `
                           -Check 'NetshHelper' -BaselineSeverity 'High' -AlwaysReport `
                           -ExtraEvidence @{ 'Note' = 'netsh helper DLLs load whenever netsh.exe runs' }
    }

    foreach ($monitorRoot in @('HKLM:\SYSTEM\CurrentControlSet\Control\Print\Monitors')) {
        if (-not (Test-Path -LiteralPath $monitorRoot)) { continue }
        foreach ($monitor in (Get-ChildItem -LiteralPath $monitorRoot -ErrorAction SilentlyContinue)) {
            $dll = Get-RegistryValue -Path $monitor.PSPath -Name 'Driver'
            if ([string]::IsNullOrWhiteSpace("$dll")) { continue }

            $dllPath = Expand-PathVariables -Path "$dll"
            if ($dllPath -notmatch '[\\/]') { $dllPath = Join-Path "$env:SystemRoot\System32" $dllPath }
            $signature = Get-SignatureInfo -Path $dllPath
            if ($signature.IsMicrosoft) { continue }

            Add-AutorunFinding -Source 'Print monitor' -Name $monitor.PSChildName -CommandLine $dllPath `
                               -Check 'PrintMonitor' -BaselineSeverity 'High' -AlwaysReport `
                               -ExtraEvidence @{ 'Note' = 'Print monitor DLLs are loaded by the spooler service as SYSTEM' }
        }
    }
}

function Invoke-PersistenceChecks {
    Invoke-Check -Name 'RunKeys'              -Body { Test-RunKeys }
    Invoke-Check -Name 'StartupFolders'       -Body { Test-StartupFolders }
    Invoke-Check -Name 'ScheduledTasks'       -Body { Test-ScheduledTasks }
    Invoke-Check -Name 'Services'             -Body { Test-Services }
    Invoke-Check -Name 'WmiSubscriptions'     -Body { Test-WmiSubscriptions }
    Invoke-Check -Name 'IFEO'                 -Body { Test-ImageFileExecutionOptions }
    Invoke-Check -Name 'WinlogonAppInitLsa'   -Body { Test-WinlogonAndAppInit }
    Invoke-Check -Name 'ComHijacks'           -Body { Test-ComHijacks }
    Invoke-Check -Name 'PowerShellProfiles'   -Body { Test-PowerShellProfiles }
    Invoke-Check -Name 'ExplorerExtensions'   -Body { Test-ExplorerExtensionPoints }
    Invoke-Check -Name 'BootAndDrivers'       -Body { Test-BootAndDriverPersistence }
    Invoke-Check -Name 'NetshAndPrint'        -Body { Test-NetshAndPrintPersistence }
}

# ============================ lib/Checks.Defender.ps1 ============================
<#
    Checks.Defender.ps1 - Defender health, tampering and OS hardening posture.

    The premise of this module: Defender will never tell you that Defender has
    been weakened. Exclusion paths, disabled ASR rules, downgraded UAC and
    WDigest credential caching are all *configuration*, so they generate no
    detection - but they are exactly what an attacker changes first.
#>

$script:DefenderCategory = 'Defender & Hardening'

# Attack Surface Reduction rules, by GUID. Action 1 = Block, 2 = Audit, 6 = Warn.
$script:AsrRules = @{
    '56a863a9-875e-4185-98a7-b882c64b5ce5' = 'Block abuse of exploited vulnerable signed drivers'
    '7674ba52-37eb-4a4f-a9a1-f0f9a1619a2c' = 'Block Adobe Reader from creating child processes'
    'd4f940ab-401b-4efc-aadc-ad5f3c50688a' = 'Block all Office applications from creating child processes'
    '9e6c4e1f-7d60-472f-ba1a-a39ef669e4b2' = 'Block credential stealing from LSASS'
    'be9ba2d9-53ea-4cdc-84e5-9b1eeee46550' = 'Block executable content from email and webmail'
    '01443614-cd74-433a-b99e-2ecdc07bfc25' = 'Block executables unless they meet prevalence/age criteria'
    '5beb7efe-fd9a-4556-801d-275e5ffc04cc' = 'Block execution of potentially obfuscated scripts'
    'd3e037e1-3eb8-44c8-a917-57927947596d' = 'Block JS/VBScript from launching downloaded content'
    '3b576869-a4ec-4529-8536-b80a7769e899' = 'Block Office applications from creating executable content'
    '75668c1f-73b5-4cf0-bb93-3ecf5cb7cc84' = 'Block Office applications from injecting into other processes'
    '26190899-1602-49e8-8b27-eb1d0a1ce869' = 'Block Office communication apps from creating child processes'
    'e6db77e5-3df2-4cf1-b95a-636979351e5b' = 'Block persistence through WMI event subscription'
    'd1e49aac-8f56-4280-b9ba-993a6d77406c' = 'Block process creations from PSExec and WMI commands'
    'b2b3f03d-6a65-4f7b-a9c7-1c7ef74a9ba4' = 'Block untrusted/unsigned processes running from USB'
    'c0033c00-d16d-4114-a5a0-dc9b3a7d2ceb' = 'Block use of copied or impersonated system tools'
    '92e97fa1-2edf-4476-bdd6-9dd0b4dddc7b' = 'Block Win32 API calls from Office macros'
    'c1db55ab-c21a-4637-bb3f-a12568109d35' = 'Use advanced protection against ransomware'
}

function Test-DefenderStatus {
    Write-ScanLog -Message 'Defender engine status' -Level 'Step'

    $status = $null
    try { $status = Get-MpComputerStatus -ErrorAction Stop } catch { }

    if (-not $status) {
        Add-Finding -Category $script:DefenderCategory -Check 'DefenderStatus' -Severity 'High' `
                    -Title 'Microsoft Defender status could not be read' `
                    -Detail 'Get-MpComputerStatus failed. Either Defender has been removed/replaced by another AV product, the Defender service is not running, or the scan is not elevated.' `
                    -Recommendation 'Run this scanner from an elevated PowerShell prompt. If it still fails, check that the WinDefend service is running and that a third-party AV has not disabled it.' `
                    -Evidence ([ordered]@{ 'Elevated scan' = (Test-IsElevated) })
        return
    }

    $toggles = @(
        @{ Name = 'RealTimeProtectionEnabled'; Label = 'Real-time protection';  Severity = 'Critical' }
        @{ Name = 'AntivirusEnabled';          Label = 'Antivirus engine';       Severity = 'Critical' }
        @{ Name = 'AntispywareEnabled';        Label = 'Antispyware engine';     Severity = 'Critical' }
        @{ Name = 'BehaviorMonitorEnabled';    Label = 'Behaviour monitoring';   Severity = 'High' }
        @{ Name = 'IoavProtectionEnabled';     Label = 'Downloaded file scanning'; Severity = 'High' }
        @{ Name = 'OnAccessProtectionEnabled'; Label = 'On-access protection';   Severity = 'High' }
        @{ Name = 'NISEnabled';                Label = 'Network inspection';     Severity = 'Medium' }
    )

    foreach ($toggle in $toggles) {
        if (-not $status.PSObject.Properties[$toggle.Name]) { continue }
        if ($status.($toggle.Name)) { continue }

        Add-Finding -Category $script:DefenderCategory -Check 'DefenderStatus' -Severity $toggle.Severity `
                    -Title "$($toggle.Label) is disabled" `
                    -Detail "Defender reports $($toggle.Name) = False. If you did not turn this off yourself, something else did." `
                    -Recommendation 'Re-enable in Windows Security > Virus & threat protection. If the setting reverts or is greyed out, a policy or a running process is holding it off - investigate before trusting the machine.' `
                    -Evidence ([ordered]@{ 'Setting' = $toggle.Name; 'Value' = 'False' })
    }

    if ($status.PSObject.Properties['IsTamperProtected'] -and -not $status.IsTamperProtected) {
        Add-Finding -Category $script:DefenderCategory -Check 'DefenderStatus' -Severity 'High' `
                    -Title 'Tamper Protection is off' `
                    -Detail 'Without Tamper Protection, any process running as administrator can silently disable Defender features or add exclusions.' `
                    -Recommendation 'Turn on Windows Security > Virus & threat protection > Manage settings > Tamper Protection.' `
                    -Evidence ([ordered]@{ 'IsTamperProtected' = 'False' })
    }

    if ($status.PSObject.Properties['AntivirusSignatureAge']) {
        $age = [int]$status.AntivirusSignatureAge
        if ($age -gt 7) {
            $severity = if ($age -gt 30) { 'High' } else { 'Medium' }
            Add-Finding -Category $script:DefenderCategory -Check 'DefenderStatus' -Severity $severity `
                        -Title "Defender signatures are $age days old" `
                        -Detail 'Stale definitions usually mean update delivery is broken or has been deliberately blocked (a common step after an initial compromise).' `
                        -Recommendation 'Run Update-MpSignature. If it fails, check the hosts file and proxy findings in this report - update endpoints are a frequent blackhole target.' `
                        -Evidence ([ordered]@{
                            'Signature age (days)' = $age
                            'Last update'          = $status.AntivirusSignatureLastUpdated
                            'Signature version'    = $status.AntivirusSignatureVersion
                        })
        }
    }

    $lastScan = $null
    foreach ($property in @('FullScanEndTime','QuickScanEndTime')) {
        if ($status.PSObject.Properties[$property] -and $status.$property) {
            if (-not $lastScan -or $status.$property -gt $lastScan) { $lastScan = $status.$property }
        }
    }
    if (-not $lastScan) {
        Add-Finding -Category $script:DefenderCategory -Check 'DefenderStatus' -Severity 'Low' `
                    -Title 'No completed Defender scan is recorded' `
                    -Detail 'Neither a quick nor a full scan has a recorded end time.' `
                    -Recommendation 'Run Start-MpScan -ScanType QuickScan to establish a baseline.' `
                    -Evidence ([ordered]@{ 'FullScanEndTime' = $status.FullScanEndTime; 'QuickScanEndTime' = $status.QuickScanEndTime })
    }
    elseif (((Get-Date) - $lastScan).TotalDays -gt 14) {
        Add-Finding -Category $script:DefenderCategory -Check 'DefenderStatus' -Severity 'Low' `
                    -Title "Last Defender scan was $([int](((Get-Date) - $lastScan).TotalDays)) days ago" `
                    -Detail 'Real-time protection covers most cases, but a periodic full scan catches dormant files written before a signature existed.' `
                    -Recommendation 'Run Start-MpScan -ScanType FullScan.' `
                    -Evidence ([ordered]@{ 'Last scan' = $lastScan })
    }
}

function Test-DefenderExclusions {
    <#
        .SYNOPSIS
        Exclusions are the single highest-value tampering target: adding one is
        a supported operation that produces no alert, and everything inside it
        becomes invisible to Defender permanently.
    #>
    Write-ScanLog -Message 'Defender exclusions' -Level 'Step'

    $preference = $null
    try { $preference = Get-MpPreference -ErrorAction Stop } catch { return }

    $exclusionTypes = @(
        @{ Property = 'ExclusionPath';      Label = 'path' }
        @{ Property = 'ExclusionProcess';   Label = 'process' }
        @{ Property = 'ExclusionExtension'; Label = 'extension' }
        @{ Property = 'ExclusionIpAddress'; Label = 'IP address' }
    )

    foreach ($type in $exclusionTypes) {
        if (-not $preference.PSObject.Properties[$type.Property]) { continue }
        $values = @($preference.($type.Property)) | Where-Object { $_ }
        if ($values.Count -eq 0) { continue }

        foreach ($value in $values) {
            $text = "$value"
            $severity = 'Medium'
            $notes = New-Object System.Collections.ArrayList

            # An exclusion whose scope is enormous is functionally "AV off".
            if ($text -match '^[A-Za-z]:\\?$' -or $text -match '^[A-Za-z]:\\(Users|Windows|ProgramData|Program Files)\\?$' -or $text -eq '*') {
                $severity = 'Critical'
                $null = $notes.Add('This exclusion covers a top-level directory, which removes Defender coverage from a huge portion of the disk')
            }
            elseif ($text -match '\\Temp\\?$|\\AppData\\?|\\Downloads\\?$|\\Public\\?$') {
                $severity = 'High'
                $null = $notes.Add('This exclusion covers a directory malware routinely writes to')
            }
            if ($type.Property -eq 'ExclusionExtension' -and $text -match '^\.?(exe|dll|ps1|js|vbs|bat|cmd|scr)$') {
                $severity = 'Critical'
                $null = $notes.Add('Excluding an executable file type disables scanning of that type everywhere on the machine')
            }
            if ($type.Property -eq 'ExclusionProcess') {
                $null = $notes.Add('Files touched by this process are not scanned while it runs')
            }

            $detail = "Defender is configured to skip this $($type.Label). "
            if ($notes.Count -gt 0) { $detail += ($notes -join '. ') + '. ' }
            $detail += 'Exclusions are invisible in normal Defender reporting and are commonly added by an attacker to create a safe staging area.'

            Add-Finding -Category $script:DefenderCategory -Check 'DefenderExclusions' -Severity $severity `
                        -Title "Defender exclusion ($($type.Label)): $text" `
                        -Detail $detail `
                        -Recommendation "If you did not add this yourself, remove it with Remove-MpPreference -$($type.Property) '$text' and then run a full scan of the excluded location." `
                        -Evidence ([ordered]@{ 'Exclusion type' = $type.Property; 'Value' = $text })
        }
    }

    # Feature-level opt-outs stored in preferences.
    $disableFlags = @(
        @{ Name = 'DisableRealtimeMonitoring';   Label = 'Real-time monitoring';        Severity = 'Critical' }
        @{ Name = 'DisableBehaviorMonitoring';   Label = 'Behaviour monitoring';        Severity = 'High' }
        @{ Name = 'DisableScriptScanning';       Label = 'Script scanning';             Severity = 'High' }
        @{ Name = 'DisableArchiveScanning';      Label = 'Archive scanning';            Severity = 'Medium' }
        @{ Name = 'DisableIOAVProtection';       Label = 'Downloaded file scanning';    Severity = 'High' }
        @{ Name = 'DisableRemovableDriveScanning'; Label = 'Removable drive scanning';  Severity = 'Low' }
        @{ Name = 'DisableBlockAtFirstSeen';     Label = 'Block at first sight';        Severity = 'High' }
    )
    foreach ($flag in $disableFlags) {
        if (-not $preference.PSObject.Properties[$flag.Name]) { continue }
        if (-not $preference.($flag.Name)) { continue }

        Add-Finding -Category $script:DefenderCategory -Check 'DefenderExclusions' -Severity $flag.Severity `
                    -Title "$($flag.Label) has been switched off in Defender preferences" `
                    -Detail "Get-MpPreference reports $($flag.Name) = True." `
                    -Recommendation "Re-enable with Set-MpPreference -$($flag.Name) `$false" `
                    -Evidence ([ordered]@{ 'Preference' = $flag.Name; 'Value' = 'True' })
    }

    if ($preference.PSObject.Properties['MAPSReporting'] -and [int]$preference.MAPSReporting -eq 0) {
        Add-Finding -Category $script:DefenderCategory -Check 'DefenderExclusions' -Severity 'Medium' `
                    -Title 'Cloud-delivered protection (MAPS) is disabled' `
                    -Detail 'Without cloud lookups, Defender is limited to local signatures and loses most of its ability to catch novel samples.' `
                    -Recommendation 'Set-MpPreference -MAPSReporting Advanced' `
                    -Evidence ([ordered]@{ 'MAPSReporting' = $preference.MAPSReporting })
    }

    if ($preference.PSObject.Properties['PUAProtection'] -and [int]$preference.PUAProtection -eq 0) {
        Add-Finding -Category $script:DefenderCategory -Check 'DefenderExclusions' -Severity 'Low' `
                    -Title 'Potentially Unwanted Application protection is off' `
                    -Detail 'PUA protection covers adware, bundleware and many "grey" remote-access tools that the antivirus engine deliberately does not treat as malware.' `
                    -Recommendation 'Set-MpPreference -PUAProtection Enabled' `
                    -Evidence ([ordered]@{ 'PUAProtection' = $preference.PUAProtection })
    }
}

function Test-AsrRules {
    Write-ScanLog -Message 'Attack Surface Reduction rules' -Level 'Step'

    $preference = $null
    try { $preference = Get-MpPreference -ErrorAction Stop } catch { return }
    if (-not $preference.PSObject.Properties['AttackSurfaceReductionRules_Ids']) { return }

    $ids     = @($preference.AttackSurfaceReductionRules_Ids)
    $actions = @($preference.AttackSurfaceReductionRules_Actions)

    $configured = @{}
    for ($i = 0; $i -lt $ids.Count; $i++) {
        if (-not $ids[$i]) { continue }
        $action = if ($i -lt $actions.Count) { [int]$actions[$i] } else { 0 }
        $configured["$($ids[$i])".ToLowerInvariant()] = $action
    }

    # The rules that matter most for a home/workstation threat model.
    $highValue = @(
        '9e6c4e1f-7d60-472f-ba1a-a39ef669e4b2'  # LSASS credential theft
        'e6db77e5-3df2-4cf1-b95a-636979351e5b'  # WMI persistence
        'd4f940ab-401b-4efc-aadc-ad5f3c50688a'  # Office child processes
        '5beb7efe-fd9a-4556-801d-275e5ffc04cc'  # Obfuscated scripts
        'be9ba2d9-53ea-4cdc-84e5-9b1eeee46550'  # Executable content from email
        'd3e037e1-3eb8-44c8-a917-57927947596d'  # JS/VBS launching downloads
        '92e97fa1-2edf-4476-bdd6-9dd0b4dddc7b'  # Win32 calls from macros
        '3b576869-a4ec-4529-8536-b80a7769e899'  # Office creating executables
        'c1db55ab-c21a-4637-bb3f-a12568109d35'  # Ransomware protection
        '56a863a9-875e-4185-98a7-b882c64b5ce5'  # Vulnerable signed drivers
    )

    $notBlocking = New-Object System.Collections.ArrayList
    foreach ($id in $highValue) {
        $action = if ($configured.ContainsKey($id)) { $configured[$id] } else { 0 }
        if ($action -eq 1) { continue }
        $state = switch ($action) { 2 { 'Audit only' } 6 { 'Warn only' } default { 'Not configured' } }
        $null = $notBlocking.Add("$($script:AsrRules[$id]) - $state")
    }

    if ($notBlocking.Count -gt 0) {
        $severity = if ($notBlocking.Count -ge 8) { 'High' } else { 'Medium' }
        Add-Finding -Category $script:DefenderCategory -Check 'AsrRules' -Severity $severity `
                    -Title "$($notBlocking.Count) of $($highValue.Count) high-value ASR rules are not in Block mode" `
                    -Detail 'Attack Surface Reduction rules block whole techniques rather than specific files, so they stop malware that has no signature. They are off by default on consumer Windows, which is why this is worth fixing even on a clean machine.' `
                    -Recommendation 'Enable with: Add-MpPreference -AttackSurfaceReductionRules_Ids <GUID> -AttackSurfaceReductionRules_Actions Enabled. Start in Audit mode (-Actions AuditMode) if you are worried about breaking an application.' `
                    -Evidence ([ordered]@{ 'Rules not blocking' = ($notBlocking -join ' | ') })
    }

    # A rule explicitly configured to Disabled (0) is different from unset.
    foreach ($id in $configured.Keys) {
        if ($configured[$id] -ne 0) { continue }
        if (-not $script:AsrRules.ContainsKey($id)) { continue }
        Add-Finding -Category $script:DefenderCategory -Check 'AsrRules' -Severity 'Medium' `
                    -Title "ASR rule explicitly disabled: $($script:AsrRules[$id])" `
                    -Detail 'This rule has been configured and then set to Disabled, which is a deliberate action rather than a default.' `
                    -Recommendation "Re-enable with Add-MpPreference -AttackSurfaceReductionRules_Ids $id -AttackSurfaceReductionRules_Actions Enabled" `
                    -Evidence ([ordered]@{ 'Rule GUID' = $id; 'Action' = 'Disabled (0)' })
    }
}

function Test-DefenderPolicyOverrides {
    Write-ScanLog -Message 'Defender policy overrides in the registry' -Level 'Step'

    $policyChecks = @(
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender'; Name = 'DisableAntiSpyware'; Label = 'Defender is disabled by policy'; Severity = 'Critical' }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender'; Name = 'DisableAntiVirus';   Label = 'Defender antivirus is disabled by policy'; Severity = 'Critical' }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection'; Name = 'DisableRealtimeMonitoring'; Label = 'Real-time monitoring is disabled by policy'; Severity = 'Critical' }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection'; Name = 'DisableBehaviorMonitoring'; Label = 'Behaviour monitoring is disabled by policy'; Severity = 'High' }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection'; Name = 'DisableScanOnRealtimeEnable'; Label = 'Real-time scan-on-enable is disabled by policy'; Severity = 'High' }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Spynet'; Name = 'SpynetReporting'; Label = 'Cloud protection disabled by policy'; Severity = 'Medium'; ExpectZeroIsBad = $true }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Reporting'; Name = 'DisableEnhancedNotifications'; Label = 'Defender notifications suppressed by policy'; Severity = 'Medium' }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Microsoft Antimalware'; Name = 'DisableAntiSpyware'; Label = 'Legacy antimalware policy disables Defender'; Severity = 'Critical' }
    )

    foreach ($check in $policyChecks) {
        $value = Get-RegistryValue -Path $check.Path -Name $check.Name
        if ($null -eq $value) { continue }

        $isBad = if ($check.ContainsKey('ExpectZeroIsBad') -and $check.ExpectZeroIsBad) { [int]$value -eq 0 } else { [int]$value -eq 1 }
        if (-not $isBad) { continue }

        Add-Finding -Category $script:DefenderCategory -Check 'DefenderPolicy' -Severity $check.Severity `
                    -Title $check.Label `
                    -Detail "A Group Policy registry value is forcing this setting off. On an unmanaged home PC nothing should be writing these keys, so their presence is itself suspicious - this is a common way to keep Defender down across reboots." `
                    -Recommendation "Delete the value $($check.Name) under $($check.Path), then reboot and confirm Defender comes back up." `
                    -Evidence ([ordered]@{ 'Key' = $check.Path; 'Value name' = $check.Name; 'Data' = $value })
    }

    # Windows Security Center notification suppression.
    $wscNotify = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Microsoft\Windows Defender Security Center\Notifications' -Name 'DisableNotifications'
    if ([int]$wscNotify -eq 1) {
        Add-Finding -Category $script:DefenderCategory -Check 'DefenderPolicy' -Severity 'Medium' `
                    -Title 'Windows Security notifications are suppressed' `
                    -Detail 'Alerts from Windows Security will not be shown, so a detection could happen without you ever seeing it.' `
                    -Recommendation 'Set DisableNotifications to 0 under HKLM\SOFTWARE\Microsoft\Windows Defender Security Center\Notifications.' `
                    -Evidence ([ordered]@{ 'DisableNotifications' = $wscNotify })
    }
}

function Test-DefenderServiceHealth {
    Write-ScanLog -Message 'Security service health' -Level 'Step'

    $services = @(
        @{ Name = 'WinDefend';   Label = 'Microsoft Defender Antivirus Service'; Severity = 'Critical' }
        @{ Name = 'WdNisSvc';    Label = 'Defender Network Inspection Service';  Severity = 'Medium' }
        @{ Name = 'Sense';       Label = 'Defender for Endpoint sensor';         Severity = 'Low' }
        @{ Name = 'SecurityHealthService'; Label = 'Windows Security Health Service'; Severity = 'Medium' }
        @{ Name = 'wscsvc';      Label = 'Security Center Service';              Severity = 'Medium' }
        @{ Name = 'MpsSvc';      Label = 'Windows Defender Firewall Service';    Severity = 'High' }
        @{ Name = 'EventLog';    Label = 'Windows Event Log';                    Severity = 'High' }
        @{ Name = 'Schedule';    Label = 'Task Scheduler';                       Severity = 'Medium' }
    )

    foreach ($entry in $services) {
        $service = Get-Service -Name $entry.Name -ErrorAction SilentlyContinue
        if (-not $service) { continue }

        $startMode = $null
        try { $startMode = (Get-CimInstance Win32_Service -Filter "Name='$($entry.Name)'" -ErrorAction Stop).StartMode } catch { }

        if ($service.Status -ne 'Running') {
            Add-Finding -Category $script:DefenderCategory -Check 'ServiceHealth' -Severity $entry.Severity `
                        -Title "$($entry.Label) is not running" `
                        -Detail "Service '$($entry.Name)' is in state $($service.Status) with start mode $startMode." `
                        -Recommendation "Start it with Start-Service $($entry.Name). If it will not start or stops again, treat that as active interference." `
                        -Evidence ([ordered]@{ 'Service' = $entry.Name; 'Status' = "$($service.Status)"; 'Start mode' = $startMode })
        }
        elseif ($startMode -eq 'Disabled') {
            Add-Finding -Category $script:DefenderCategory -Check 'ServiceHealth' -Severity $entry.Severity `
                        -Title "$($entry.Label) is set to Disabled" `
                        -Detail 'The service is running now but will not start after the next reboot.' `
                        -Recommendation "Set-Service $($entry.Name) -StartupType Automatic" `
                        -Evidence ([ordered]@{ 'Service' = $entry.Name; 'Start mode' = 'Disabled' })
        }
    }

    # Anything else registered as the active AV product.
    try {
        $products = @(Get-CimInstance -Namespace 'root\SecurityCenter2' -ClassName 'AntiVirusProduct' -ErrorAction Stop)
        $thirdParty = @($products | Where-Object { $_.displayName -notmatch 'Windows Defender|Microsoft Defender' })
        if ($thirdParty.Count -gt 0) {
            Add-Finding -Category $script:DefenderCategory -Check 'ServiceHealth' -Severity 'Info' `
                        -Title "Third-party antivirus registered: $(($thirdParty | ForEach-Object { $_.displayName }) -join ', ')" `
                        -Detail 'When another AV registers itself, Defender steps down to passive mode. That is expected - but verify you actually installed these products.' `
                        -Recommendation 'Remove any AV product you do not recognise; rogue "security" software is a common malware disguise.' `
                        -Evidence ([ordered]@{ 'Products' = (($products | ForEach-Object { $_.displayName }) -join ', ') })
        }
    }
    catch { }
}

function Test-CredentialHardening {
    <#
        .SYNOPSIS
        Settings that decide how easy it is to steal credentials off this box.
        None of these produce an antivirus detection when changed.
    #>
    Write-ScanLog -Message 'Credential exposure settings' -Level 'Step'

    $wdigest = Get-RegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest' -Name 'UseLogonCredential'
    if ([int]$wdigest -eq 1) {
        Add-Finding -Category $script:DefenderCategory -Check 'CredentialHardening' -Severity 'Critical' `
                    -Title 'WDigest is caching plaintext credentials in memory' `
                    -Detail 'UseLogonCredential = 1 forces Windows to keep your password in cleartext inside lsass.exe. This is off by default on modern Windows and is one of the first things an attacker enables after gaining admin, because it turns a memory dump into a plaintext password.' `
                    -Recommendation 'Set UseLogonCredential to 0 under HKLM\SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest, reboot, and change your password from a known-clean device.' `
                    -Evidence ([ordered]@{ 'UseLogonCredential' = $wdigest })
    }

    $runAsPpl = Get-RegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name 'RunAsPPL'
    if ([int]$runAsPpl -ne 1) {
        Add-Finding -Category $script:DefenderCategory -Check 'CredentialHardening' -Severity 'Medium' `
                    -Title 'LSA Protection (RunAsPPL) is not enabled' `
                    -Detail 'LSA Protection runs lsass.exe as a protected process, which blocks most credential-dumping tools from reading its memory even with administrator rights.' `
                    -Recommendation 'Set RunAsPPL to 1 (DWORD) under HKLM\SYSTEM\CurrentControlSet\Control\Lsa and reboot. Check for driver compatibility first if you use smartcard or third-party auth software.' `
                    -Evidence ([ordered]@{ 'RunAsPPL' = if ($null -eq $runAsPpl) { 'not set' } else { $runAsPpl } })
    }

    $restrictAnonymous = Get-RegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name 'RestrictAnonymous'
    if ([int]$restrictAnonymous -eq 0) {
        Add-Finding -Category $script:DefenderCategory -Check 'CredentialHardening' -Severity 'Low' `
                    -Title 'Anonymous enumeration of accounts and shares is permitted' `
                    -Detail 'RestrictAnonymous = 0 lets an unauthenticated network peer list local accounts and shares.' `
                    -Recommendation 'Set RestrictAnonymous to 1 and RestrictAnonymousSAM to 1 under HKLM\SYSTEM\CurrentControlSet\Control\Lsa.' `
                    -Evidence ([ordered]@{ 'RestrictAnonymous' = $restrictAnonymous })
    }

    # Cleartext autologon password.
    $autoLogon = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'DefaultPassword'
    if ($autoLogon) {
        Add-Finding -Category $script:DefenderCategory -Check 'CredentialHardening' -Severity 'High' `
                    -Title 'A logon password is stored in cleartext in the registry' `
                    -Detail 'Winlogon\DefaultPassword holds an account password in plain text, readable by any process running as that user. This is set up by the autologon feature.' `
                    -Recommendation 'Remove the DefaultPassword value. If you need autologon, use Sysinternals Autologon, which stores the secret in the LSA instead.' `
                    -Evidence ([ordered]@{
                        'DefaultUserName' = (Get-RegistryValue -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'DefaultUserName')
                        'AutoAdminLogon'  = (Get-RegistryValue -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoAdminLogon')
                        'Password stored' = 'yes (value not printed)'
                    })
    }
}

function Test-SystemHardening {
    Write-ScanLog -Message 'System hardening posture' -Level 'Step'

    # --- UAC -------------------------------------------------------------
    $systemPolicy = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'
    $enableLua    = Get-RegistryValue -Path $systemPolicy -Name 'EnableLUA'
    $consent      = Get-RegistryValue -Path $systemPolicy -Name 'ConsentPromptBehaviorAdmin'
    $secureDesk   = Get-RegistryValue -Path $systemPolicy -Name 'PromptOnSecureDesktop'
    $tokenFilter  = Get-RegistryValue -Path $systemPolicy -Name 'LocalAccountTokenFilterPolicy'

    if ($null -ne $enableLua -and [int]$enableLua -eq 0) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Critical' `
                    -Title 'User Account Control is completely disabled' `
                    -Detail 'EnableLUA = 0 means every process started by an administrator runs fully elevated with no prompt. It also disables the sandboxing that protects Edge and other applications.' `
                    -Recommendation 'Set EnableLUA to 1 and reboot.' `
                    -Evidence ([ordered]@{ 'EnableLUA' = $enableLua })
    }
    elseif ($null -ne $consent -and [int]$consent -eq 0) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'High' `
                    -Title 'UAC elevates administrators without prompting' `
                    -Detail 'ConsentPromptBehaviorAdmin = 0 ("Elevate without prompting") lets any process silently gain full administrator rights.' `
                    -Recommendation 'Set ConsentPromptBehaviorAdmin to 2 (always prompt on the secure desktop).' `
                    -Evidence ([ordered]@{ 'ConsentPromptBehaviorAdmin' = $consent })
    }
    elseif ($null -ne $consent -and [int]$consent -eq 5 -and $null -ne $secureDesk -and [int]$secureDesk -eq 0) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Medium' `
                    -Title 'UAC prompts are not shown on the secure desktop' `
                    -Detail 'With PromptOnSecureDesktop = 0 the consent dialog can be manipulated by other software running in your session.' `
                    -Recommendation 'Set PromptOnSecureDesktop to 1.' `
                    -Evidence ([ordered]@{ 'PromptOnSecureDesktop' = $secureDesk; 'ConsentPromptBehaviorAdmin' = $consent })
    }

    if ([int]$tokenFilter -eq 1) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'High' `
                    -Title 'Remote UAC filtering is disabled (LocalAccountTokenFilterPolicy)' `
                    -Detail 'This lets local accounts connect over the network with a full administrator token. It is a requirement for most remote lateral-movement techniques and is not a Windows default.' `
                    -Recommendation 'Delete LocalAccountTokenFilterPolicy, or set it to 0, under HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System.' `
                    -Evidence ([ordered]@{ 'LocalAccountTokenFilterPolicy' = $tokenFilter })
    }

    # --- SMBv1 -----------------------------------------------------------
    $smb1 = $null
    try { $smb1 = Get-SmbServerConfiguration -ErrorAction Stop } catch { }
    if ($smb1 -and $smb1.PSObject.Properties['EnableSMB1Protocol'] -and $smb1.EnableSMB1Protocol) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'High' `
                    -Title 'SMBv1 is enabled' `
                    -Detail 'SMBv1 is the protocol exploited by EternalBlue/WannaCry. It has no message signing worth the name and is deprecated; Windows has not needed it since Windows 7 era devices.' `
                    -Recommendation 'Disable with: Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol' `
                    -Evidence ([ordered]@{ 'EnableSMB1Protocol' = 'True' })
    }
    if ($smb1 -and $smb1.PSObject.Properties['RequireSecuritySignature'] -and -not $smb1.RequireSecuritySignature) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Low' `
                    -Title 'SMB signing is not required' `
                    -Detail 'Without required signing, SMB sessions can be relayed by an attacker on the same network.' `
                    -Recommendation 'Set-SmbServerConfiguration -RequireSecuritySignature $true' `
                    -Evidence ([ordered]@{ 'RequireSecuritySignature' = 'False' })
    }

    # --- RDP -------------------------------------------------------------
    $denyRdp = Get-RegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -Name 'fDenyTSConnections'
    if ($null -ne $denyRdp -and [int]$denyRdp -eq 0) {
        $nla  = Get-RegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name 'UserAuthentication'
        $port = Get-RegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name 'PortNumber'

        $severity = if ([int]$nla -ne 1) { 'High' } else { 'Medium' }
        $detail = 'Remote Desktop accepts incoming connections on this machine. '
        if ([int]$nla -ne 1) { $detail += 'Network Level Authentication is OFF, so an attacker reaches the logon screen - and the pre-auth attack surface - without any credentials. ' }
        $detail += 'RDP brute-forcing is one of the most common ways home and small-business machines are taken over.'

        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity $severity `
                    -Title 'Remote Desktop is enabled' `
                    -Detail $detail `
                    -Recommendation 'If you do not use RDP, turn it off in Settings > System > Remote Desktop. If you do, require Network Level Authentication, never expose port 3389 to the internet, and put it behind a VPN.' `
                    -Evidence ([ordered]@{
                        'fDenyTSConnections'   = $denyRdp
                        'NLA (UserAuthentication)' = if ($null -eq $nla) { 'not set' } else { $nla }
                        'Listening port'       = if ($null -eq $port) { '3389 (default)' } else { $port }
                    })
    }

    # --- Firewall --------------------------------------------------------
    try {
        foreach ($firewallProfile in (Get-NetFirewallProfile -ErrorAction Stop)) {
            if (-not $firewallProfile.Enabled) {
                Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'High' `
                            -Title "Firewall is off for the $($firewallProfile.Name) profile" `
                            -Detail 'With the firewall disabled, every listening service on this machine is reachable from the network it is attached to.' `
                            -Recommendation "Set-NetFirewallProfile -Profile $($firewallProfile.Name) -Enabled True" `
                            -Evidence ([ordered]@{ 'Profile' = $firewallProfile.Name; 'Enabled' = 'False' })
            }
            elseif ("$($firewallProfile.DefaultInboundAction)" -eq 'Allow') {
                Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'High' `
                            -Title "Firewall default inbound action is Allow ($($firewallProfile.Name) profile)" `
                            -Detail 'The firewall is enabled but permits unsolicited inbound traffic by default, which negates most of its value.' `
                            -Recommendation "Set-NetFirewallProfile -Profile $($firewallProfile.Name) -DefaultInboundAction Block" `
                            -Evidence ([ordered]@{ 'Profile' = $firewallProfile.Name; 'DefaultInboundAction' = 'Allow' })
            }
        }
    }
    catch { }

    # --- Boot integrity --------------------------------------------------
    try {
        $secureBoot = Confirm-SecureBootUEFI -ErrorAction Stop
        if (-not $secureBoot) {
            Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Medium' `
                        -Title 'Secure Boot is disabled' `
                        -Detail 'Secure Boot prevents unsigned bootloaders and boot-level rootkits from loading before Windows. It is also a prerequisite for several other protections.' `
                        -Recommendation 'Enable Secure Boot in UEFI firmware settings.' `
                        -Evidence ([ordered]@{ 'Secure Boot' = 'Disabled' })
        }
    }
    catch { }

    # --- BitLocker -------------------------------------------------------
    try {
        $systemVolume = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop
        if ("$($systemVolume.ProtectionStatus)" -ne 'On') {
            Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Medium' `
                        -Title "BitLocker is not protecting $env:SystemDrive" `
                        -Detail 'Without full-disk encryption, anyone with physical access can read every file and extract credential material by booting from USB - no password needed.' `
                        -Recommendation 'Enable BitLocker (or Device Encryption on Home editions) and store the recovery key somewhere off this machine.' `
                        -Evidence ([ordered]@{
                            'Mount point'       = $systemVolume.MountPoint
                            'Protection status' = "$($systemVolume.ProtectionStatus)"
                            'Encryption'        = "$($systemVolume.VolumeStatus)"
                        })
        }
    }
    catch { }

    # --- Script visibility ----------------------------------------------
    $scriptBlockLogging = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging' -Name 'EnableScriptBlockLogging'
    if ([int]$scriptBlockLogging -ne 1) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Low' `
                    -Title 'PowerShell script block logging is off' `
                    -Detail 'Script block logging records the actual code PowerShell executes, after de-obfuscation. Without it, an encoded malicious command leaves almost no forensic trace.' `
                    -Recommendation 'Create HKLM\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging and set EnableScriptBlockLogging = 1 (DWORD). Events land in Microsoft-Windows-PowerShell/Operational, ID 4104.' `
                    -Evidence ([ordered]@{ 'EnableScriptBlockLogging' = if ($null -eq $scriptBlockLogging) { 'not set' } else { $scriptBlockLogging } })
    }

    # PowerShell v2 bypasses v5's logging and AMSI entirely.
    try {
        $v2 = Get-WindowsOptionalFeature -Online -FeatureName MicrosoftWindowsPowerShellV2 -ErrorAction Stop
        if ($v2 -and "$($v2.State)" -eq 'Enabled') {
            Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Medium' `
                        -Title 'PowerShell v2 engine is installed' `
                        -Detail 'The v2 engine predates AMSI and script block logging. Running powershell.exe -Version 2 downgrades into it and silently bypasses both Defender script scanning and all logging.' `
                        -Recommendation 'Disable-WindowsOptionalFeature -Online -FeatureName MicrosoftWindowsPowerShellV2Root' `
                        -Evidence ([ordered]@{ 'Feature state' = "$($v2.State)" })
        }
    }
    catch { }

    # --- Installer privilege escalation ----------------------------------
    $alwaysElevatedMachine = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Installer' -Name 'AlwaysInstallElevated'
    $alwaysElevatedUser    = Get-RegistryValue -Path 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer' -Name 'AlwaysInstallElevated'
    if ([int]$alwaysElevatedMachine -eq 1 -and [int]$alwaysElevatedUser -eq 1) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Critical' `
                    -Title 'AlwaysInstallElevated is enabled for both machine and user' `
                    -Detail 'Any user on this machine can install an MSI package that runs as SYSTEM. This is a one-command privilege escalation to full system control and requires no exploit.' `
                    -Recommendation 'Set AlwaysInstallElevated to 0 in both HKLM and HKCU under SOFTWARE\Policies\Microsoft\Windows\Installer.' `
                    -Evidence ([ordered]@{ 'HKLM value' = $alwaysElevatedMachine; 'HKCU value' = $alwaysElevatedUser })
    }

    # --- Removable media autorun -----------------------------------------
    $noDriveTypeAutoRun = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer' -Name 'NoDriveTypeAutoRun'
    if ($null -eq $noDriveTypeAutoRun -or ([int]$noDriveTypeAutoRun -band 0xFF) -ne 0xFF) {
        Add-Finding -Category $script:DefenderCategory -Check 'Hardening' -Severity 'Low' `
                    -Title 'AutoRun is not fully disabled for all drive types' `
                    -Detail 'AutoRun/AutoPlay on removable media is a long-standing infection route for USB-borne malware.' `
                    -Recommendation 'Set NoDriveTypeAutoRun to 255 (0xFF) under HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer.' `
                    -Evidence ([ordered]@{ 'NoDriveTypeAutoRun' = if ($null -eq $noDriveTypeAutoRun) { 'not set' } else { $noDriveTypeAutoRun } })
    }
}

function Test-PatchLevel {
    Write-ScanLog -Message 'Patch level' -Level 'Step'

    # Get-HotFix only reflects the classic QFE mechanism and routinely misses
    # the cumulative updates that carry most of the actual security fixes on
    # Windows 10/11, which can make a fully patched machine look stale. Cross
    # -check against Windows Update's own last-success timestamp and trust
    # whichever source is more recent.
    $candidates = New-Object System.Collections.ArrayList

    try {
        $latestHotfix = Get-HotFix -ErrorAction Stop |
                        Where-Object { $_.InstalledOn } |
                        Sort-Object InstalledOn -Descending |
                        Select-Object -First 1
        if ($latestHotfix) {
            $null = $candidates.Add([pscustomobject]@{ Date = $latestHotfix.InstalledOn; Source = "Hotfix $($latestHotfix.HotFixID)" })
        }
    }
    catch { }

    $lastSuccess = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Install' -Name 'LastSuccessTime'
    if ($lastSuccess) {
        $parsed = [datetime]::MinValue
        if ([datetime]::TryParse("$lastSuccess", [ref]$parsed)) {
            $null = $candidates.Add([pscustomobject]@{ Date = $parsed; Source = 'Windows Update history' })
        }
    }

    if ($candidates.Count -gt 0) {
        $latest = $candidates | Sort-Object Date -Descending | Select-Object -First 1
        $age = ((Get-Date) - $latest.Date).TotalDays
        if ($age -gt 60) {
            $severity = if ($age -gt 120) { 'High' } else { 'Medium' }
            Add-Finding -Category $script:DefenderCategory -Check 'PatchLevel' -Severity $severity `
                        -Title "No Windows update installed in $([int]$age) days" `
                        -Detail 'Unpatched machines are exploited through vulnerabilities that no antivirus product will catch, because the exploit runs inside a trusted process.' `
                        -Recommendation 'Run Windows Update. If updates are failing or the service is disabled, resolve that first - blocked updates are a common post-compromise action.' `
                        -Evidence ([ordered]@{
                            'Most recent update' = $latest.Date
                            'Source'             = $latest.Source
                            'Days ago'           = [int]$age
                        })
        }
    }

    $wuService = Get-Service -Name wuauserv -ErrorAction SilentlyContinue
    if ($wuService) {
        $startMode = $null
        try { $startMode = (Get-CimInstance Win32_Service -Filter "Name='wuauserv'" -ErrorAction Stop).StartMode } catch { }
        if ($startMode -eq 'Disabled') {
            Add-Finding -Category $script:DefenderCategory -Check 'PatchLevel' -Severity 'High' `
                        -Title 'Windows Update service is disabled' `
                        -Detail 'The machine will not receive security patches or Defender platform updates.' `
                        -Recommendation 'Set-Service wuauserv -StartupType Manual and check for updates.' `
                        -Evidence ([ordered]@{ 'Start mode' = 'Disabled'; 'Status' = "$($wuService.Status)" })
        }
    }
}

function Invoke-DefenderChecks {
    Invoke-Check -Name 'DefenderStatus'      -Body { Test-DefenderStatus }
    Invoke-Check -Name 'DefenderExclusions'  -Body { Test-DefenderExclusions }
    Invoke-Check -Name 'AsrRules'            -Body { Test-AsrRules }
    Invoke-Check -Name 'DefenderPolicy'      -Body { Test-DefenderPolicyOverrides }
    Invoke-Check -Name 'ServiceHealth'       -Body { Test-DefenderServiceHealth }
    Invoke-Check -Name 'CredentialHardening' -Body { Test-CredentialHardening }
    Invoke-Check -Name 'SystemHardening'     -Body { Test-SystemHardening }
    Invoke-Check -Name 'PatchLevel'          -Body { Test-PatchLevel }
}

# ============================ lib/Checks.Network.ps1 ============================
<#
    Checks.Network.ps1 - Network exposure and trust-store integrity.

    Two themes here. First, what on this machine is reachable or talking out,
    attributed to the binary responsible. Second, the plumbing that decides
    where traffic goes and who it trusts - hosts file, DNS, proxy/PAC and the
    root certificate store. A rogue root CA is completely invisible to
    Defender and silently defeats HTTPS for every application on the box.
#>

$script:NetworkCategory = 'Network & Trust'

function Test-ListeningPorts {
    Write-ScanLog -Message 'Listening ports' -Level 'Step'

    $listeners = $null
    try { $listeners = @(Get-NetTCPConnection -State Listen -ErrorAction Stop) } catch { }
    if (-not $listeners) { return }

    # Ports Windows itself always has open; not interesting on their own.
    $expectedSystemPorts = @(135, 445, 139, 5985, 5986, 49664, 49665, 49666, 49667, 49668, 49669, 49670)

    foreach ($listener in $listeners) {
        $process   = Get-ProcessForPid -ProcessId $listener.OwningProcess
        $imagePath = if ($process) { $process.Path } else { $null }
        $signature = Get-SignatureInfo -Path $imagePath

        $leaf = if ($imagePath) { try { Split-Path $imagePath -Leaf } catch { '' } } else { '' }
        $isLolBin = [bool]($leaf -and $script:LolBinNames -contains $leaf.ToLowerInvariant())

        $isWildcard = ("$($listener.LocalAddress)" -eq '0.0.0.0' -or "$($listener.LocalAddress)" -eq '::')
        $isLoopback = ("$($listener.LocalAddress)" -eq '127.0.0.1' -or "$($listener.LocalAddress)" -eq '::1')

        $reasons    = New-Object System.Collections.ArrayList
        $severities = New-Object System.Collections.ArrayList

        foreach ($reason in (Test-SuspiciousPath -Path $imagePath)) {
            $null = $reasons.Add($reason)
            $null = $severities.Add('High')
        }

        if ($imagePath -and $signature.Exists -and -not $signature.IsMicrosoft) {
            if (-not $signature.IsSigned) {
                $null = $reasons.Add('The listening process is not digitally signed')
                $null = $severities.Add(($(if ($isWildcard) { 'High' } else { 'Medium' })))
            }
            elseif (-not $signature.IsTrusted) {
                $null = $reasons.Add("The listening process has an invalid signature ($($signature.Status))")
                $null = $severities.Add('High')
            }
        }

        if (-not $imagePath -and $listener.OwningProcess -gt 4) {
            $null = $reasons.Add('The owning process image could not be read, which can indicate a protected or hidden process')
            $null = $severities.Add('Medium')
        }

        # A wildcard bind on a high port is the classic shape of a backdoor or
        # an unintentionally exposed service. Signed Microsoft binaries are
        # normally excluded as noise, but known execution-proxy LOLBins are
        # Microsoft-signed by definition and must not get a free pass here.
        if ($isWildcard -and (-not $signature.IsMicrosoft -or $isLolBin) -and $expectedSystemPorts -notcontains [int]$listener.LocalPort) {
            $null = $reasons.Add("Accepts connections from any network interface on port $($listener.LocalPort)$(if ($isLolBin) { " - held by $leaf, a signed Windows utility commonly abused to proxy network activity" })")
            $null = $severities.Add('Medium')
        }

        if ($isLoopback -and $reasons.Count -eq 0) { continue }
        if ($reasons.Count -eq 0) { continue }

        $severity = Get-WorstSeverity -Severities @($severities) -Default 'Low'

        Add-Finding -Category $script:NetworkCategory -Check 'ListeningPorts' -Severity $severity `
                    -Title "Port $($listener.LocalPort) is open, held by $(if ($process) { $process.Name } else { "PID $($listener.OwningProcess)" })" `
                    -Detail ($reasons -join '; ') `
                    -Recommendation 'Confirm the program should be accepting connections. If you do not recognise it, stop the process, block the port in Windows Firewall, and investigate the binary.' `
                    -Evidence ([ordered]@{
                        'Local endpoint' = "$($listener.LocalAddress):$($listener.LocalPort)"
                        'Process'        = if ($process) { "$($process.Name) (PID $($process.Id))" } else { "PID $($listener.OwningProcess)" }
                        'Image'          = $imagePath
                        'Signature'      = if ($signature.Exists) { "$($signature.Status) $($signature.Signer)" } else { 'unknown' }
                        'Publisher'      = $signature.Company
                    })
    }
}

function Test-OutboundConnections {
    Write-ScanLog -Message 'Established outbound connections' -Level 'Step'

    $connections = $null
    try { $connections = @(Get-NetTCPConnection -State Established -ErrorAction Stop) } catch { }
    if (-not $connections) { return }

    $reported = @{}

    foreach ($connection in $connections) {
        $remote = "$($connection.RemoteAddress)"
        if ($remote -match '^(127\.|::1$|0\.0\.0\.0)') { continue }
        # Private ranges: normal LAN chatter, not egress.
        if ($remote -match '^(10\.|192\.168\.|169\.254\.|fe80:)') { continue }
        if ($remote -match '^172\.(1[6-9]|2[0-9]|3[0-1])\.') { continue }

        $process   = Get-ProcessForPid -ProcessId $connection.OwningProcess
        $imagePath = if ($process) { $process.Path } else { $null }
        if (-not $imagePath) { continue }

        $signature = Get-SignatureInfo -Path $imagePath
        $leaf = try { Split-Path $imagePath -Leaf } catch { '' }
        $isLolBin = [bool]($leaf -and $script:LolBinNames -contains $leaf.ToLowerInvariant())

        # Microsoft-signed binaries are normally excluded as noise, but the
        # LOLBin list is Microsoft-signed by definition - a C2 channel proxied
        # through mshta/rundll32/certutil/etc. must not be waved through here.
        if ($signature.IsMicrosoft -and -not $isLolBin) { continue }

        $reasons = @(Test-SuspiciousPath -Path $imagePath)
        if (-not $signature.IsMicrosoft) {
            if (-not $signature.IsSigned)       { $reasons += 'The connecting process is unsigned' }
            elseif (-not $signature.IsTrusted)  { $reasons += "The connecting process has an invalid signature ($($signature.Status))" }
        }
        if ($isLolBin) { $reasons += "The connection is held by $leaf, a signed Windows utility frequently abused as a network proxy for malware (living-off-the-land)" }
        if ($reasons.Count -eq 0) { continue }

        # One finding per binary, not per socket.
        $key = $imagePath.ToLowerInvariant()
        if ($reported.ContainsKey($key)) { continue }
        $reported[$key] = $true

        $peers = @($connections |
                   Where-Object { $_.OwningProcess -eq $connection.OwningProcess } |
                   ForEach-Object { "$($_.RemoteAddress):$($_.RemotePort)" } |
                   Select-Object -Unique -First 12)

        $severity = if ($signature.IsMicrosoft) { 'Medium' } else { 'High' }
        $titlePrefix = if ($signature.IsMicrosoft) { 'Signed LOLBin' } else { 'Unsigned process' }

        Add-Finding -Category $script:NetworkCategory -Check 'OutboundConnections' -Severity $severity `
                    -Title "$titlePrefix '$($process.Name)' has active internet connections" `
                    -Detail (($reasons -join '; ') + '. ' + $(if ($signature.IsMicrosoft) { 'A genuine Windows utility holding open outbound sessions can be entirely legitimate network activity, or it can be malware proxying its traffic through a trusted binary to avoid exactly this kind of check.' } else { 'An unsigned binary holding open outbound sessions is the normal shape of command-and-control or data exfiltration traffic.' })) `
                    -Recommendation 'Identify the program. If you cannot attribute it to software you installed, kill the process, block it in the firewall, and submit the file to VirusTotal before deleting.' `
                    -Evidence ([ordered]@{
                        'Process'    = "$($process.Name) (PID $($process.Id))"
                        'Image'      = $imagePath
                        'Signature'  = "$($signature.Status) $($signature.Signer)"
                        'Publisher'  = $signature.Company
                        'Remote endpoints' = ($peers -join ', ')
                    })
    }
}

function Test-HostsFile {
    Write-ScanLog -Message 'Hosts file' -Level 'Step'

    $hostsPath = "$env:SystemRoot\System32\drivers\etc\hosts"
    if (-not (Test-Path -LiteralPath $hostsPath)) { return }

    $lines = @()
    try { $lines = @(Get-Content -LiteralPath $hostsPath -ErrorAction Stop) } catch { return }

    # Domains whose blackholing is a strong signal of tampering: it keeps the
    # machine from updating or from reporting a detection.
    $securityDomains = 'microsoft\.com|windowsupdate|defender|msftncsi|msftconnecttest|sophos|mcafee|symantec|norton|kaspersky|avast|avg\.|bitdefender|eset|trendmicro|malwarebytes|virustotal|clamav|f-secure|comodo|sucuri|threatfire'

    $entries = New-Object System.Collections.ArrayList
    $lineNumber = 0
    foreach ($line in $lines) {
        $lineNumber++
        $trimmed = "$line".Trim()
        if ($trimmed.Length -eq 0 -or $trimmed.StartsWith('#')) { continue }

        $parts = $trimmed -split '\s+'
        if ($parts.Count -lt 2) { continue }

        $address   = $parts[0]
        $hostnames = @($parts[1..($parts.Count - 1)] | Where-Object { $_ -and -not $_.StartsWith('#') })
        if ($hostnames.Count -eq 0) { continue }

        # The stock file's own localhost entries.
        if ($hostnames.Count -eq 1 -and $hostnames[0] -match '^(localhost|::1)$') { continue }

        $null = $entries.Add([pscustomobject]@{ Line = $lineNumber; Address = $address; Hosts = $hostnames })
    }

    if ($entries.Count -eq 0) { return }

    $securityHits = @($entries | Where-Object { ($_.Hosts -join ' ') -match $securityDomains })
    if ($securityHits.Count -gt 0) {
        Add-Finding -Category $script:NetworkCategory -Check 'HostsFile' -Severity 'Critical' `
                    -Title 'Hosts file blackholes security or update domains' `
                    -Detail 'Entries in the hosts file redirect antivirus, telemetry or Windows Update hostnames. This is a deliberate step to stop the machine from receiving definition updates or reporting a detection, and it is one of the clearest indicators of an active infection.' `
                    -Recommendation "Open $hostsPath as administrator and remove these entries, then run Update-MpSignature and check for Windows updates." `
                    -Evidence ([ordered]@{
                        'Entries' = (($securityHits | ForEach-Object { "line $($_.Line): $($_.Address) $($_.Hosts -join ' ')" }) -join ' | ')
                        'File'    = $hostsPath
                    })
    }

    $redirects = @($entries | Where-Object {
        $_.Address -notmatch '^(0\.0\.0\.0|127\.0\.0\.1|::1)$' -and ($_.Hosts -join ' ') -notmatch $securityDomains
    })
    if ($redirects.Count -gt 0) {
        Add-Finding -Category $script:NetworkCategory -Check 'HostsFile' -Severity 'High' `
                    -Title "Hosts file redirects $($redirects.Count) hostname(s) to a specific address" `
                    -Detail 'These entries send traffic for a real hostname to an address of someone else''s choosing, bypassing DNS entirely. Legitimate uses exist (development, ad blocking), but this is also how a phishing page is made to appear at a bank''s address.' `
                    -Recommendation "Review each entry in $hostsPath and remove anything you did not add." `
                    -Evidence ([ordered]@{
                        'Entries' = (($redirects | Select-Object -First 25 | ForEach-Object { "line $($_.Line): $($_.Address) -> $($_.Hosts -join ' ')" }) -join ' | ')
                    })
    }

    $blocked = @($entries | Where-Object { $_.Address -match '^(0\.0\.0\.0|127\.0\.0\.1)$' -and ($_.Hosts -join ' ') -notmatch $securityDomains })
    if ($blocked.Count -gt 50) {
        Add-Finding -Category $script:NetworkCategory -Check 'HostsFile' -Severity 'Info' `
                    -Title "Hosts file blocks $($blocked.Count) hostnames" `
                    -Detail 'A large blocklist is typical of an ad-blocking hosts file. Noted for completeness rather than as a problem.' `
                    -Recommendation 'No action needed if you installed a hosts-based ad blocker.' `
                    -Evidence ([ordered]@{ 'Blocked entries' = $blocked.Count; 'Sample' = (($blocked | Select-Object -First 5 | ForEach-Object { $_.Hosts -join ' ' }) -join ', ') })
    }
}

function Test-DnsConfiguration {
    Write-ScanLog -Message 'DNS configuration' -Level 'Step'

    # Well-known resolvers, so a deliberate choice is not reported as a hijack.
    $knownResolvers = @(
        '8.8.8.8','8.8.4.4','1.1.1.1','1.0.0.1','9.9.9.9','149.112.112.112',
        '208.67.222.222','208.67.220.220','76.76.2.0','76.76.10.0','94.140.14.14','94.140.15.15',
        '2001:4860:4860::8888','2001:4860:4860::8844','2606:4700:4700::1111','2620:fe::fe'
    )

    try {
        $adapters = @(Get-DnsClientServerAddress -AddressFamily IPv4 -ErrorAction Stop |
                      Where-Object { $_.ServerAddresses -and $_.ServerAddresses.Count -gt 0 })

        foreach ($adapter in $adapters) {
            $state = $null
            try { $state = Get-NetAdapter -InterfaceIndex $adapter.InterfaceIndex -ErrorAction Stop } catch { }
            if ($state -and "$($state.Status)" -ne 'Up') { continue }

            foreach ($server in $adapter.ServerAddresses) {
                if ($knownResolvers -contains $server) { continue }
                # Router-assigned resolvers on the local network are normal.
                if ($server -match '^(10\.|192\.168\.|127\.)') { continue }
                if ($server -match '^172\.(1[6-9]|2[0-9]|3[0-1])\.') { continue }

                Add-Finding -Category $script:NetworkCategory -Check 'DnsConfiguration' -Severity 'High' `
                            -Title "Unrecognised public DNS server configured: $server" `
                            -Detail "Adapter '$($adapter.InterfaceAlias)' resolves names using a public address that is neither your local router nor a well-known resolver. Whoever runs that server decides where every hostname on this machine points - including your bank and your update servers." `
                            -Recommendation 'Unless you deliberately configured this resolver, reset the adapter to obtain DNS automatically (Settings > Network > adapter > Edit DNS > Automatic).' `
                            -Evidence ([ordered]@{
                                'Adapter'     = $adapter.InterfaceAlias
                                'DNS servers' = ($adapter.ServerAddresses -join ', ')
                            })
            }
        }
    }
    catch { }

    # DNS over the NRPT / policy path can silently override adapter settings.
    try {
        $nrpt = @(Get-DnsClientNrptRule -ErrorAction Stop)
        foreach ($rule in $nrpt) {
            if (-not $rule.NameServers) { continue }
            Add-Finding -Category $script:NetworkCategory -Check 'DnsConfiguration' -Severity 'Medium' `
                        -Title "DNS policy rule redirects '$($rule.Namespace)'" `
                        -Detail 'A Name Resolution Policy Table rule overrides normal DNS for this namespace. Common in corporate/VPN setups, unusual on a personal machine.' `
                        -Recommendation 'If this machine is not managed by an employer and you do not run a VPN that installs DNS policy, remove the rule with Remove-DnsClientNrptRule.' `
                        -Evidence ([ordered]@{
                            'Namespace'   = ($rule.Namespace -join ', ')
                            'Name servers'= ($rule.NameServers -join ', ')
                        })
        }
    }
    catch { }
}

function Test-ProxyConfiguration {
    <#
        .SYNOPSIS
        Proxy and PAC settings.

        AutoConfigURL is the standout: it points at a remotely-hosted script
        that decides the route for every request, it is writable per-user
        without admin rights, and Defender has no opinion about it whatsoever.
    #>
    Write-ScanLog -Message 'Proxy and PAC configuration' -Level 'Step'

    foreach ($hive in (Get-UserHivePaths)) {
        $settingsKey = Join-Path $hive.Root 'SOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings'
        if (-not (Test-Path -LiteralPath $settingsKey)) { continue }

        $autoConfigUrl = Get-RegistryValue -Path $settingsKey -Name 'AutoConfigURL'
        if (-not [string]::IsNullOrWhiteSpace("$autoConfigUrl")) {
            Add-Finding -Category $script:NetworkCategory -Check 'ProxyConfiguration' -Severity 'Critical' `
                        -Title "Automatic proxy configuration script is set for $($hive.User)" `
                        -Detail "Every HTTP and HTTPS request from this user is routed according to a script fetched from '$autoConfigUrl'. Whoever controls that URL controls where your traffic goes, can selectively route banking or webmail through their own server, and can change the rules at any time without touching this machine again." `
                        -Recommendation "Unless your workplace configured this, clear it: Remove-ItemProperty -Path '$settingsKey' -Name AutoConfigURL, then restart your browsers." `
                        -Evidence ([ordered]@{ 'User' = $hive.User; 'AutoConfigURL' = "$autoConfigUrl"; 'Key' = $settingsKey })
        }

        $proxyEnable = Get-RegistryValue -Path $settingsKey -Name 'ProxyEnable'
        $proxyServer = Get-RegistryValue -Path $settingsKey -Name 'ProxyServer'
        if ([int]$proxyEnable -eq 1 -and -not [string]::IsNullOrWhiteSpace("$proxyServer")) {
            $severity = if ("$proxyServer" -match '^(127\.0\.0\.1|localhost)') { 'Medium' } else { 'High' }
            $detail = "Traffic for $($hive.User) is routed through '$proxyServer'. "
            $detail += if ($severity -eq 'Medium') {
                'The proxy is local, which is typical of a debugging tool, a VPN client or a content filter - but also of an interception implant.'
            } else {
                'A remote proxy sees, and can modify, every unencrypted request. Combined with an installed root certificate it can read HTTPS too.'
            }

            Add-Finding -Category $script:NetworkCategory -Check 'ProxyConfiguration' -Severity $severity `
                        -Title "HTTP proxy is configured for $($hive.User)" `
                        -Detail $detail `
                        -Recommendation 'Check Settings > Network & Internet > Proxy. If you did not set this up, turn it off and cross-reference the root certificate findings in this report.' `
                        -Evidence ([ordered]@{
                            'User'        = $hive.User
                            'ProxyServer' = "$proxyServer"
                            'ProxyOverride' = (Get-RegistryValue -Path $settingsKey -Name 'ProxyOverride')
                        })
        }
    }

    # WinHTTP has its own proxy, used by services and by Windows Update.
    try {
        $winHttp = & netsh winhttp show proxy 2>$null | Out-String
        if ($winHttp -match 'Proxy Server\(s\)\s*:\s*(?<proxy>\S+)') {
            Add-Finding -Category $script:NetworkCategory -Check 'ProxyConfiguration' -Severity 'High' `
                        -Title "A system-wide WinHTTP proxy is set: $($Matches['proxy'])" `
                        -Detail 'WinHTTP is used by Windows services rather than by browsers - including Windows Update and Defender cloud lookups. A proxy here can quietly break or intercept those.' `
                        -Recommendation 'Clear it with: netsh winhttp reset proxy' `
                        -Evidence ([ordered]@{ 'netsh output' = ConvertTo-DisplayString $winHttp 400 })
        }
    }
    catch { }
}

function Test-RootCertificates {
    <#
        .SYNOPSIS
        Non-Microsoft roots in the trusted store.

        A certificate here can sign a TLS certificate for any website and every
        browser will accept it silently. Installing one is not malware and
        triggers no AV detection, which is exactly why interception tooling
        does it.
    #>
    Write-ScanLog -Message 'Trusted root certificate store' -Level 'Step'

    # Roots that ship with Windows or are added by common, legitimate software.
    $expectedIssuers = @(
        'Microsoft', 'DigiCert', 'VeriSign', 'GlobalSign', 'Baltimore', 'Thawte',
        'GeoTrust', 'Go Daddy', 'Entrust', 'COMODO', 'Sectigo', 'USERTrust',
        'AddTrust', 'Certum', 'QuoVadis', 'SecureTrust', 'Starfield', 'Symantec',
        'ISRG Root', "Let's Encrypt", 'Amazon Root', 'Google Trust Services', 'GTS Root',
        'Actalis', 'Buypass', 'D-TRUST', 'E-Tugra', 'HARICA', 'Hongkong Post',
        'IdenTrust', 'Network Solutions', 'SSL.com', 'SwissSign', 'T-TeleSec',
        'TWCA', 'TeliaSonera', 'Trustwave', 'UCA ', 'XRamp', 'Cybertrust',
        'AAA Certificate Services', 'Certigna', 'Chambers of Commerce', 'DST Root',
        'GDCA', 'GlobalTrust', 'ANF ', 'AC RAIZ', 'Autoridad', 'CFCA', 'OISTE',
        'SZAFIR', 'Security Communication', 'Staat der Nederlanden', 'TrustCor',
        'emSign', 'vTrus', 'Atos', 'Certainly', 'SecureSign', 'NAVER', 'Telia'
    )

    $stores = @(
        @{ Location = 'LocalMachine'; Name = 'Root';     Label = 'machine trusted roots';   BaseSeverity = 'High' }
        @{ Location = 'CurrentUser';  Name = 'Root';     Label = 'user trusted roots';      BaseSeverity = 'Critical' }
        @{ Location = 'LocalMachine'; Name = 'CA';       Label = 'machine intermediate CAs'; BaseSeverity = 'Medium' }
    )

    foreach ($storeSpec in $stores) {
        $certificates = @()
        try {
            $certificates = @(Get-ChildItem -Path "Cert:\$($storeSpec.Location)\$($storeSpec.Name)" -ErrorAction Stop)
        }
        catch { continue }

        foreach ($certificate in $certificates) {
            $subject = "$($certificate.Subject)"
            $issuer  = "$($certificate.Issuer)"

            $selfSigned = ($subject -eq $issuer)

            # The Subject field is free text the certificate's own author
            # chose, so a rogue self-signed root can simply name itself
            # "Microsoft Corporation" or "DigiCert Trusted Root" and defeat a
            # bare substring match. A name match only counts as a real pass
            # when the certificate isn't a freshly-minted self-signed one -
            # genuine bundled Windows/major-CA roots are long established,
            # not something appearing with a recent issue date.
            $recognised = $false
            foreach ($known in $expectedIssuers) {
                if ($subject -like "*$known*") { $recognised = $true; break }
            }
            $recentlyIssued = ($certificate.NotBefore -gt (Get-Date).AddYears(-2))
            $nameLikelySpoofed = ($recognised -and $selfSigned -and $recentlyIssued)
            if ($recognised -and -not $nameLikelySpoofed) { continue }

            $reasons  = New-Object System.Collections.ArrayList
            $severity = $storeSpec.BaseSeverity

            if ($nameLikelySpoofed) {
                $severity = 'Critical'
                $null = $reasons.Add("The subject name matches a known CA ('$(Get-CommonName $subject)'), but this certificate is self-signed and was issued recently - genuine Windows/major-CA roots are long-established and are never distributed this way, so a trusted-sounding name here is a red flag rather than a pass")
            }
            elseif ($selfSigned) {
                $null = $reasons.Add('The certificate is self-signed, so nobody vouched for it but itself')
            }

            # Interception proxies name themselves; this catches the honest ones.
            if ($subject -match 'Fiddler|Charles|Burp|mitmproxy|BrowserStack|Zscaler|Netskope|Forcepoint|Blue ?Coat|Cisco Umbrella|Kaspersky Anti-Virus Personal Root|AVG|Avast|ESET SSL Filter|BitDefender Personal|DO_NOT_TRUST') {
                $null = $reasons.Add('The subject name matches a known TLS-interception product - traffic to every HTTPS site can be decrypted by whatever holds this key')
                $severity = 'Critical'
            }

            if ($certificate.NotBefore -gt (Get-Date).AddDays(-90)) {
                $null = $reasons.Add("The certificate was issued recently ($($certificate.NotBefore.ToString('yyyy-MM-dd')))")
            }
            if ($certificate.NotAfter -lt (Get-Date)) {
                $null = $reasons.Add("The certificate expired on $($certificate.NotAfter.ToString('yyyy-MM-dd')) and should have been removed")
            }
            if ($storeSpec.Location -eq 'CurrentUser') {
                $null = $reasons.Add('It sits in the per-user store, which can be written without administrator rights')
            }

            if ($reasons.Count -eq 0) { $null = $reasons.Add('The issuer is not one that ships with Windows or with mainstream software') }

            Add-Finding -Category $script:NetworkCategory -Check 'RootCertificates' -Severity $severity `
                        -Title "Unrecognised certificate authority in $($storeSpec.Label): $(Get-CommonName $subject)" `
                        -Detail (($reasons -join '; ') + '. A certificate in this store can vouch for any website on the internet, so software holding the matching private key can present a valid-looking certificate for your bank and no browser will warn you.') `
                        -Recommendation "If you cannot attribute this to software you installed (corporate VPN, antivirus with HTTPS scanning, a developer proxy), remove it: Get-ChildItem Cert:\$($storeSpec.Location)\$($storeSpec.Name)\$($certificate.Thumbprint) | Remove-Item" `
                        -Evidence ([ordered]@{
                            'Store'      = "Cert:\$($storeSpec.Location)\$($storeSpec.Name)"
                            'Subject'    = $subject
                            'Issuer'     = $issuer
                            'Thumbprint' = $certificate.Thumbprint
                            'Valid from' = $certificate.NotBefore
                            'Valid to'   = $certificate.NotAfter
                            'Self-signed'= $selfSigned
                        })
        }
    }
}

function Test-SharesAndFirewallRules {
    Write-ScanLog -Message 'Network shares and inbound firewall rules' -Level 'Step'

    try {
        $shares = @(Get-SmbShare -ErrorAction Stop | Where-Object { $_.Name -notmatch '^\w\$$' -and $_.Name -ne 'IPC$' -and $_.Name -ne 'ADMIN$' })
        foreach ($share in $shares) {
            $openTo = @()
            try {
                $openTo = @(Get-SmbShareAccess -Name $share.Name -ErrorAction Stop |
                            Where-Object { $_.AccessControlType -eq 'Allow' -and "$($_.AccountName)" -match 'Everyone|ANONYMOUS|Guests' })
            }
            catch { }

            $severity = if ($openTo.Count -gt 0) { 'High' } else { 'Low' }
            $detail = "The folder '$($share.Path)' is shared on the network as '$($share.Name)'. "
            if ($openTo.Count -gt 0) {
                $detail += 'It grants access to Everyone/Anonymous, so any device on the same network can reach it without credentials. This is a common route for ransomware to spread between machines.'
            }

            Add-Finding -Category $script:NetworkCategory -Check 'Shares' -Severity $severity `
                        -Title "SMB share '$($share.Name)' is published" `
                        -Detail $detail `
                        -Recommendation 'Remove shares you no longer use with Remove-SmbShare, and never grant Everyone write access on a machine that connects to public networks.' `
                        -Evidence ([ordered]@{
                            'Share' = $share.Name
                            'Path'  = $share.Path
                            'Open access grants' = if ($openTo.Count -gt 0) { (($openTo | ForEach-Object { "$($_.AccountName): $($_.AccessRight)" }) -join ', ') } else { 'none' }
                        })
        }
    }
    catch { }

    try {
        $rules = @(Get-NetFirewallRule -Direction Inbound -Action Allow -Enabled True -ErrorAction Stop |
                   Where-Object { "$($_.Profile)" -match 'Public|Any' })

        foreach ($rule in $rules) {
            $applicationFilter = $null
            try { $applicationFilter = Get-NetFirewallApplicationFilter -AssociatedNetFirewallRule $rule -ErrorAction Stop } catch { }
            $program = if ($applicationFilter) { "$($applicationFilter.Program)" } else { 'Any' }
            if ($program -eq 'Any' -or [string]::IsNullOrWhiteSpace($program)) { continue }

            $resolved  = Expand-PathVariables -Path $program
            $signature = Get-SignatureInfo -Path $resolved
            if ($signature.IsMicrosoft) { continue }

            $reasons = @(Test-SuspiciousPath -Path $resolved)
            if ($signature.Exists -and -not $signature.IsSigned) { $reasons += 'The allowed program is unsigned' }
            if (-not $signature.Exists) { $reasons += 'The allowed program no longer exists on disk (stale rule)' }
            if ($reasons.Count -eq 0) { continue }

            $portFilter = $null
            try { $portFilter = Get-NetFirewallPortFilter -AssociatedNetFirewallRule $rule -ErrorAction Stop } catch { }

            Add-Finding -Category $script:NetworkCategory -Check 'FirewallRules' -Severity 'High' `
                        -Title "Firewall rule '$($rule.DisplayName)' opens the public profile to an untrusted program" `
                        -Detail (($reasons -join '; ') + '. Inbound allow rules on the Public profile apply on untrusted networks such as cafe and hotel Wi-Fi.') `
                        -Recommendation "Remove the rule if you do not recognise it: Remove-NetFirewallRule -Name '$($rule.Name)'" `
                        -Evidence ([ordered]@{
                            'Rule'      = $rule.DisplayName
                            'Program'   = $resolved
                            'Profile'   = "$($rule.Profile)"
                            'Ports'     = if ($portFilter) { "$($portFilter.Protocol) $($portFilter.LocalPort)" } else { 'any' }
                            'Signature' = if ($signature.Exists) { "$($signature.Status) $($signature.Signer)" } else { 'file missing' }
                        })
        }
    }
    catch { }
}

function Test-NameResolutionExposure {
    Write-ScanLog -Message 'LLMNR / NetBIOS name resolution' -Level 'Step'

    $llmnr = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -Name 'EnableMulticast'
    if ([int]$llmnr -ne 0) {
        Add-Finding -Category $script:NetworkCategory -Check 'NameResolution' -Severity 'Medium' `
                    -Title 'LLMNR multicast name resolution is enabled' `
                    -Detail 'When DNS fails, Windows shouts the hostname onto the local network and trusts whoever answers first. On a shared network an attacker answers every query and collects your NTLM credential hashes - a technique that needs no malware on your machine at all, so no antivirus can see it.' `
                    -Recommendation 'Create HKLM\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient and set EnableMulticast = 0 (DWORD).' `
                    -Evidence ([ordered]@{ 'EnableMulticast' = if ($null -eq $llmnr) { 'not set (enabled by default)' } else { $llmnr } })
    }

    $netbiosEnabled = New-Object System.Collections.ArrayList
    foreach ($interface in (Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces' -ErrorAction SilentlyContinue)) {
        $option = Get-RegistryValue -Path $interface.PSPath -Name 'NetbiosOptions'
        # 0 = use DHCP setting, 1 = enabled, 2 = disabled
        if ([int]$option -ne 2) { $null = $netbiosEnabled.Add($interface.PSChildName) }
    }
    if ($netbiosEnabled.Count -gt 0) {
        Add-Finding -Category $script:NetworkCategory -Check 'NameResolution' -Severity 'Low' `
                    -Title "NetBIOS over TCP/IP is not disabled on $($netbiosEnabled.Count) interface(s)" `
                    -Detail 'NBT-NS has the same credential-relay weakness as LLMNR and is obsolete on any network that has working DNS.' `
                    -Recommendation 'Set NetbiosOptions = 2 for each interface under HKLM\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces, or disable NetBIOS in the adapter''s advanced TCP/IP settings.' `
                    -Evidence ([ordered]@{ 'Interfaces' = ($netbiosEnabled -join ', ') })
    }

    # WPAD resolves a proxy config from the network - same trust problem.
    $wpadDisabled = Get-RegistryValue -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings\WinHttp' -Name 'DisableWpad'
    if ([int]$wpadDisabled -ne 1) {
        Add-Finding -Category $script:NetworkCategory -Check 'NameResolution' -Severity 'Low' `
                    -Title 'WPAD proxy auto-discovery is not disabled' `
                    -Detail 'WPAD asks the local network for proxy settings. Anyone able to answer that request can route all of your web traffic through themselves.' `
                    -Recommendation 'Set DisableWpad = 1 (DWORD) under HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings\WinHttp, and turn off "Automatically detect settings" in proxy options.' `
                    -Evidence ([ordered]@{ 'DisableWpad' = if ($null -eq $wpadDisabled) { 'not set' } else { $wpadDisabled } })
    }
}

function Invoke-NetworkChecks {
    Invoke-Check -Name 'ListeningPorts'      -Body { Test-ListeningPorts }
    Invoke-Check -Name 'OutboundConnections' -Body { Test-OutboundConnections }
    Invoke-Check -Name 'HostsFile'           -Body { Test-HostsFile }
    Invoke-Check -Name 'DnsConfiguration'    -Body { Test-DnsConfiguration }
    Invoke-Check -Name 'ProxyConfiguration'  -Body { Test-ProxyConfiguration }
    Invoke-Check -Name 'RootCertificates'    -Body { Test-RootCertificates }
    Invoke-Check -Name 'SharesAndFirewall'   -Body { Test-SharesAndFirewallRules }
    Invoke-Check -Name 'NameResolution'      -Body { Test-NameResolutionExposure }
}

# ============================ lib/Checks.Accounts.ps1 ============================
<#
    Checks.Accounts.ps1 - Local accounts and privilege escalation paths.

    Everything here is a misconfiguration rather than a file, so none of it
    produces an antivirus detection. The privilege-path checks answer a
    specific question: if a standard user (or a piece of malware running as
    one) is on this machine, what lets it become SYSTEM without an exploit?
#>

$script:AccountCategory = 'Accounts & Privilege Paths'

function Test-LocalAccounts {
    Write-ScanLog -Message 'Local accounts' -Level 'Step'

    $users = $null
    try { $users = @(Get-LocalUser -ErrorAction Stop) } catch { }
    if (-not $users) {
        try { $users = @(Get-CimInstance Win32_UserAccount -Filter "LocalAccount=True" -ErrorAction Stop) } catch { return }
    }

    # Accounts hidden from the sign-in screen. A real backdoor account is
    # usually paired with an entry here so nobody notices it exists.
    $hiddenList = @{}
    foreach ($value in (Get-RegistryValues -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon\SpecialAccounts\UserList')) {
        if ([int]$value.Value -eq 0) { $hiddenList["$($value.Name)".ToLowerInvariant()] = $true }
    }

    foreach ($user in $users) {
        $name    = "$($user.Name)"
        $enabled = if ($user.PSObject.Properties['Enabled']) { [bool]$user.Enabled } else { -not [bool]$user.Disabled }
        if (-not $enabled) { continue }

        if ($hiddenList.ContainsKey($name.ToLowerInvariant())) {
            Add-Finding -Category $script:AccountCategory -Check 'LocalAccounts' -Severity 'Critical' `
                        -Title "Account '$name' is enabled but hidden from the sign-in screen" `
                        -Detail 'A registry entry under Winlogon\SpecialAccounts\UserList hides this account from the logon UI and from the Users control panel while leaving it fully usable. There is essentially no legitimate reason for this on a personal machine - it is how a backdoor account is concealed.' `
                        -Recommendation "Delete the '$name' value under HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon\SpecialAccounts\UserList, then disable or remove the account with Disable-LocalUser -Name '$name'." `
                        -Evidence ([ordered]@{
                            'Account'    = $name
                            'Enabled'    = $enabled
                            'Last logon' = if ($user.PSObject.Properties['LastLogon']) { $user.LastLogon } else { '' }
                            'Description'= "$($user.Description)"
                        })
        }

        if ($name -match '^Guest$') {
            Add-Finding -Category $script:AccountCategory -Check 'LocalAccounts' -Severity 'High' `
                        -Title 'The Guest account is enabled' `
                        -Detail 'Guest allows password-less local and, depending on policy, network access. It is disabled by default on every supported Windows version.' `
                        -Recommendation 'Disable-LocalUser -Name Guest' `
                        -Evidence ([ordered]@{ 'Account' = $name; 'Enabled' = 'True' })
        }

        if ($user.PSObject.Properties['PasswordRequired'] -and $user.PasswordRequired -eq $false) {
            Add-Finding -Category $script:AccountCategory -Check 'LocalAccounts' -Severity 'High' `
                        -Title "Account '$name' does not require a password" `
                        -Detail 'Anyone with physical access can log in as this account, and depending on policy it may be usable over the network too.' `
                        -Recommendation "Set a password with Set-LocalUser -Name '$name' -Password (Read-Host -AsSecureString), or disable the account." `
                        -Evidence ([ordered]@{ 'Account' = $name; 'PasswordRequired' = 'False' })
        }

        # Recently created accounts are worth a look after a suspected incident.
        if ($user.PSObject.Properties['PasswordLastSet'] -and $user.PasswordLastSet) {
            $age = ((Get-Date) - $user.PasswordLastSet).TotalDays
            if ($age -lt 14 -and $name -notmatch '^(DefaultAccount|WDAGUtilityAccount|Guest|Administrator)$') {
                Add-Finding -Category $script:AccountCategory -Check 'LocalAccounts' -Severity 'Low' `
                            -Title "Account '$name' had its password set within the last $([int]$age) days" `
                            -Detail 'Noted so you can rule out an account that was created or taken over recently. Expected if you set this up yourself.' `
                            -Recommendation 'Confirm you recognise this account and this change.' `
                            -Evidence ([ordered]@{ 'Account' = $name; 'PasswordLastSet' = $user.PasswordLastSet })
            }
        }
    }

    # Administrators group membership.
    try {
        $administrators = @(Get-LocalGroupMember -Group 'Administrators' -ErrorAction Stop)
        $memberList = ($administrators | ForEach-Object { "$($_.Name) [$($_.ObjectClass)]" }) -join ', '

        $unexpected = @($administrators | Where-Object {
            "$($_.Name)" -notmatch '\\(Administrator|Domain Admins|Enterprise Admins)$' -and
            "$($_.PrincipalSource)" -ne 'MicrosoftAccount'
        })

        Add-Finding -Category $script:AccountCategory -Check 'LocalAccounts' `
                    -Severity ($(if ($administrators.Count -gt 3) { 'Medium' } else { 'Info' })) `
                    -Title "Local Administrators group has $($administrators.Count) member(s)" `
                    -Detail 'Every member here can disable Defender, add exclusions and install drivers. Confirm each one is expected; day-to-day use should be from a standard account.' `
                    -Recommendation 'Remove any member you do not recognise with Remove-LocalGroupMember -Group Administrators -Member <name>.' `
                    -Evidence ([ordered]@{
                        'Members'  = $memberList
                        'Reviewed' = if ($unexpected.Count -gt 0) { "Pay particular attention to: $(($unexpected | ForEach-Object { $_.Name }) -join ', ')" } else { 'Only default members detected' }
                    })
    }
    catch { }

    # Built-in Administrator (RID 500) enabled is unusual on modern Windows.
    try {
        $builtinAdmin = Get-LocalUser -ErrorAction Stop | Where-Object { "$($_.SID)" -match '-500$' }
        if ($builtinAdmin -and $builtinAdmin.Enabled) {
            Add-Finding -Category $script:AccountCategory -Check 'LocalAccounts' -Severity 'Medium' `
                        -Title "The built-in Administrator account ('$($builtinAdmin.Name)') is enabled" `
                        -Detail 'RID 500 is disabled by default. When enabled it is exempt from UAC prompts in the default configuration, and it is the first account name a remote attacker will try.' `
                        -Recommendation "Disable-LocalUser -Name '$($builtinAdmin.Name)' and use your own administrator account instead." `
                        -Evidence ([ordered]@{ 'Account' = $builtinAdmin.Name; 'SID' = "$($builtinAdmin.SID)"; 'Last logon' = $builtinAdmin.LastLogon })
        }
    }
    catch { }
}

function Test-PasswordPolicy {
    Write-ScanLog -Message 'Password and lockout policy' -Level 'Step'

    $output = ''
    try { $output = (& net accounts 2>$null | Out-String) } catch { return }
    if ([string]::IsNullOrWhiteSpace($output)) { return }

    if ($output -match 'Lockout threshold:\s*(?<threshold>\S+)') {
        $threshold = $Matches['threshold']
        if ($threshold -match '^(Never|0)$') {
            Add-Finding -Category $script:AccountCategory -Check 'PasswordPolicy' -Severity 'Medium' `
                        -Title 'No account lockout threshold is set' `
                        -Detail 'Passwords can be guessed indefinitely with no lockout. This matters most alongside RDP or SMB being reachable from the network.' `
                        -Recommendation 'Set a threshold: net accounts /lockoutthreshold:10 /lockoutduration:15 /lockoutwindow:15' `
                        -Evidence ([ordered]@{ 'Lockout threshold' = $threshold })
        }
    }

    if ($output -match 'Minimum password length:\s*(?<length>\d+)') {
        $length = [int]$Matches['length']
        if ($length -lt 8) {
            Add-Finding -Category $script:AccountCategory -Check 'PasswordPolicy' -Severity 'Low' `
                        -Title "Minimum password length is $length" `
                        -Detail 'Short passwords fall quickly to offline cracking if a credential hash is ever captured.' `
                        -Recommendation 'net accounts /minpwlen:14' `
                        -Evidence ([ordered]@{ 'Minimum password length' = $length })
        }
    }
}

function Test-UnquotedServicePaths {
    <#
        .SYNOPSIS
        Classic unquoted service path escalation.

        "C:\Program Files\My App\svc.exe" without quotes makes Windows try
        C:\Program.exe first. If any prefix directory is user-writable, a
        standard user plants a binary there and it runs as the service account.
    #>
    Write-ScanLog -Message 'Unquoted service paths' -Level 'Step'

    $services = $null
    try { $services = @(Get-CimInstance Win32_Service -ErrorAction Stop) } catch { return }

    foreach ($service in $services) {
        $imagePath = "$($service.PathName)"
        if ([string]::IsNullOrWhiteSpace($imagePath)) { continue }
        if ($imagePath.TrimStart().StartsWith('"')) { continue }

        # Only the executable portion matters; arguments after it are irrelevant.
        $executable = $imagePath
        if ($imagePath -match '^(?<exe>.*?\.exe)\s') { $executable = $Matches['exe'] }
        if ($executable -notmatch '\s') { continue }
        if ($executable -match '^[^\\/]*$') { continue }

        # Drivers under system32 with no spaces are not affected.
        $writablePrefixes = New-Object System.Collections.ArrayList
        $parent = Split-Path $executable -Parent
        while ($parent -and $parent -match '\\') {
            if ($parent -match '\s') {
                $acl = Test-UserWritable -Path (Split-Path $parent -Parent)
                if ($acl -and $acl.Writable) {
                    $null = $writablePrefixes.Add("$(Split-Path $parent -Parent) ($($acl.Grants -join '; '))")
                }
            }
            $next = Split-Path $parent -Parent
            if ($next -eq $parent) { break }
            $parent = $next
        }

        $severity = if ($writablePrefixes.Count -gt 0) { 'Critical' } else { 'Medium' }
        $detail = "The service '$($service.Name)' has an unquoted image path containing spaces: $imagePath. Windows will try each space-separated prefix as an executable in turn."
        if ($writablePrefixes.Count -gt 0) {
            $detail += " One of those prefix directories is writable by non-administrators, so any user on this machine can place a file there and have it run as $($service.StartName)."
        }
        else {
            $detail += ' No writable prefix directory was found, so this is currently not exploitable - but it becomes exploitable the moment permissions change.'
        }

        Add-Finding -Category $script:AccountCategory -Check 'UnquotedServicePath' -Severity $severity `
                    -Title "Unquoted service path: $($service.Name)" `
                    -Detail $detail `
                    -Recommendation "Quote the path: sc.exe config `"$($service.Name)`" binPath= `"`"$executable`"`" (keep any original arguments after the closing quote)." `
                    -Evidence ([ordered]@{
                        'Service'    = "$($service.Name) ($($service.DisplayName))"
                        'ImagePath'  = $imagePath
                        'Runs as'    = $service.StartName
                        'Start mode' = $service.StartMode
                        'Writable prefixes' = if ($writablePrefixes.Count -gt 0) { ($writablePrefixes -join ' | ') } else { 'none found' }
                    })
    }
}

function Test-WritableServiceBinaries {
    Write-ScanLog -Message 'Service binary and directory permissions' -Level 'Step'

    $services = $null
    try { $services = @(Get-CimInstance Win32_Service -ErrorAction Stop) } catch { return }

    foreach ($service in $services) {
        $imagePath = "$($service.PathName)"
        if ([string]::IsNullOrWhiteSpace($imagePath)) { continue }

        $resolved = Resolve-ExecutablePath -CommandLine $imagePath
        if (-not $resolved -or -not (Test-Path -LiteralPath $resolved -PathType Leaf -ErrorAction SilentlyContinue)) { continue }

        # Only privileged service accounts turn a write into an escalation.
        $runsAs = "$($service.StartName)"
        if ($runsAs -notmatch 'LocalSystem|NT AUTHORITY\\SYSTEM|LocalService|NetworkService') { continue }

        $fileAcl = Test-UserWritable -Path $resolved
        if ($fileAcl -and $fileAcl.Writable) {
            Add-Finding -Category $script:AccountCategory -Check 'WritableServiceBinary' -Severity 'Critical' `
                        -Title "Service binary for '$($service.Name)' is writable by non-administrators" `
                        -Detail "Any standard user can overwrite $resolved. The service runs as $runsAs, so replacing that file gives full SYSTEM code execution at the next service start or reboot. No exploit and no malware file is needed for this - which is why antivirus does not flag it." `
                        -Recommendation "Correct the ACL so only Administrators and SYSTEM can write: icacls `"$resolved`" /inheritance:r /grant `"Administrators:(F)`" `"SYSTEM:(F)`" `"Users:(RX)`"" `
                        -Evidence ([ordered]@{
                            'Service' = "$($service.Name) ($($service.DisplayName))"
                            'Binary'  = $resolved
                            'Runs as' = $runsAs
                            'Owner'   = $fileAcl.Owner
                            'Dangerous grants' = ($fileAcl.Grants -join ' | ')
                        })
            continue
        }

        # A writable containing directory permits a rename-and-replace attack.
        $directory = Split-Path $resolved -Parent
        if ($directory -match '\\Windows\\(System32|SysWOW64)$') { continue }

        $directoryAcl = Test-UserWritable -Path $directory
        if ($directoryAcl -and $directoryAcl.Writable) {
            Add-Finding -Category $script:AccountCategory -Check 'WritableServiceBinary' -Severity 'High' `
                        -Title "Directory holding service '$($service.Name)' is writable by non-administrators" `
                        -Detail "Standard users can write into $directory. Even without permission on the binary itself, a user can often replace or shadow it (or drop a DLL the service loads) and gain $runsAs privileges." `
                        -Recommendation "Restrict the directory: icacls `"$directory`" /inheritance:r /grant `"Administrators:(OI)(CI)F`" `"SYSTEM:(OI)(CI)F`" `"Users:(OI)(CI)RX`"" `
                        -Evidence ([ordered]@{
                            'Service'   = $service.Name
                            'Directory' = $directory
                            'Runs as'   = $runsAs
                            'Dangerous grants' = ($directoryAcl.Grants -join ' | ')
                        })
        }
    }
}

function Test-ServicePermissions {
    <#
        .SYNOPSIS
        Service security descriptors that let non-administrators reconfigure a
        service. SERVICE_CHANGE_CONFIG is equivalent to SYSTEM: the binary path
        can simply be repointed.
    #>
    Write-ScanLog -Message 'Service security descriptors' -Level 'Step'

    $services = $null
    try { $services = @(Get-Service -ErrorAction Stop) } catch { return }

    # SDDL identities for non-administrative principals.
    $weakPrincipals = @{
        'AU' = 'Authenticated Users'
        'BU' = 'Built-in Users'
        'WD' = 'Everyone'
        'IU' = 'Interactive Users'
        'BG' = 'Built-in Guests'
        'AN' = 'Anonymous'
    }
    # Rights that amount to control of the service.
    $dangerousRights = @{
        'RP' = 'start the service'
        'WP' = 'stop the service'
        'DT' = 'pause the service'
        'CC' = 'query configuration'
        'DC' = 'change configuration (equivalent to SYSTEM code execution)'
        'WD' = 'change permissions'
        'WO' = 'take ownership'
        'GA' = 'full control'
        'SD' = 'delete the service'
    }

    foreach ($service in $services) {
        $sddl = ''
        try { $sddl = (& sc.exe sdshow "$($service.Name)" 2>$null | Out-String).Trim() } catch { continue }
        if ([string]::IsNullOrWhiteSpace($sddl) -or $sddl -notmatch '^D:') { continue }

        foreach ($ace in [regex]::Matches($sddl, '\(A;[^;]*;(?<rights>[^;]*);[^;]*;[^;]*;(?<sid>[^\)]*)\)')) {
            $sid    = $ace.Groups['sid'].Value
            $rights = $ace.Groups['rights'].Value
            if (-not $weakPrincipals.ContainsKey($sid)) { continue }

            $granted = New-Object System.Collections.ArrayList
            foreach ($right in @('DC','WD','WO','GA','SD')) {
                if ($rights -match $right) { $null = $granted.Add($dangerousRights[$right]) }
            }
            if ($granted.Count -eq 0) { continue }

            Add-Finding -Category $script:AccountCategory -Check 'ServicePermissions' -Severity 'Critical' `
                        -Title "Service '$($service.Name)' can be reconfigured by $($weakPrincipals[$sid])" `
                        -Detail "The service security descriptor grants $($weakPrincipals[$sid]) the ability to $(($granted -join ', ')). Anyone in that group can point the service at their own executable and have it launched by the service control manager." `
                        -Recommendation "Reset the descriptor to the Windows default for this service type, or apply a restrictive one with sc.exe sdset. Verify with: sc.exe sdshow $($service.Name)" `
                        -Evidence ([ordered]@{
                            'Service'   = "$($service.Name) ($($service.DisplayName))"
                            'Principal' = "$($weakPrincipals[$sid]) ($sid)"
                            'Rights'    = $rights
                            'SDDL'      = ConvertTo-DisplayString $sddl 400
                        })
        }
    }
}

function Test-PathHijacking {
    Write-ScanLog -Message 'PATH directory permissions' -Level 'Step'

    $systemPath = Get-RegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Environment' -Name 'Path'
    if (-not $systemPath) { return }

    $index = 0
    foreach ($directory in ("$systemPath" -split ';')) {
        $index++
        $expanded = Expand-PathVariables -Path $directory
        if ([string]::IsNullOrWhiteSpace($expanded)) { continue }
        if (-not (Test-Path -LiteralPath $expanded -PathType Container -ErrorAction SilentlyContinue)) {
            # A missing PATH entry that a user can create is also a hijack.
            $parent = Split-Path $expanded -Parent
            $parentAcl = Test-UserWritable -Path $parent
            if ($parentAcl -and $parentAcl.Writable) {
                Add-Finding -Category $script:AccountCategory -Check 'PathHijack' -Severity 'High' `
                            -Title "System PATH entry '$expanded' does not exist but can be created by any user" `
                            -Detail "The directory is listed in the machine PATH but is absent. Because its parent is writable by non-administrators, a standard user can create it and place executables that will be found by name before the real ones." `
                            -Recommendation "Remove the stale entry from the system PATH, or create the directory with administrator-only write permissions." `
                            -Evidence ([ordered]@{ 'PATH entry' = $expanded; 'Position' = $index; 'Writable parent' = $parent })
            }
            continue
        }

        $acl = Test-UserWritable -Path $expanded
        if (-not $acl -or -not $acl.Writable) { continue }

        Add-Finding -Category $script:AccountCategory -Check 'PathHijack' -Severity 'Critical' `
                    -Title "System PATH directory '$expanded' is writable by non-administrators" `
                    -Detail "This directory is searched when any process runs a command by name. A standard user can drop a file such as cmd.exe or a commonly-used tool name here; when an administrator or a service later runs that command, the planted binary executes with their privileges. It is position $index in the PATH." `
                    -Recommendation "Either remove the directory from the system PATH or restrict it: icacls `"$expanded`" /inheritance:r /grant `"Administrators:(OI)(CI)F`" `"SYSTEM:(OI)(CI)F`" `"Users:(OI)(CI)RX`"" `
                    -Evidence ([ordered]@{
                        'Directory' = $expanded
                        'PATH position' = $index
                        'Owner' = $acl.Owner
                        'Dangerous grants' = ($acl.Grants -join ' | ')
                    })
    }
}

function Test-ScheduledTaskPrivilegePaths {
    Write-ScanLog -Message 'Scheduled tasks running with elevated rights' -Level 'Step'

    $tasks = $null
    try { $tasks = @(Get-ScheduledTask -ErrorAction Stop) } catch { return }

    foreach ($task in $tasks) {
        $principal = ''
        try { $principal = "$($task.Principal.UserId)" } catch { continue }
        if ($principal -notmatch 'SYSTEM|LocalService|NetworkService') { continue }
        if ($task.TaskPath -like '\Microsoft\Windows\*') { continue }

        foreach ($action in @($task.Actions)) {
            if (-not $action.PSObject.Properties['Execute']) { continue }
            $resolved = Resolve-ExecutablePath -CommandLine "$($action.Execute)"
            if (-not $resolved) { continue }

            $acl = Test-UserWritable -Path $resolved
            $target = $resolved
            if (-not ($acl -and $acl.Writable)) {
                $directory = Split-Path $resolved -Parent
                if ($directory -match '\\Windows\\(System32|SysWOW64)$') { continue }
                $acl = Test-UserWritable -Path $directory
                $target = $directory
                if (-not ($acl -and $acl.Writable)) { continue }
            }

            Add-Finding -Category $script:AccountCategory -Check 'TaskPrivilegePath' -Severity 'Critical' `
                        -Title "SYSTEM scheduled task '$($task.TaskName)' targets a user-writable location" `
                        -Detail "The task runs as $principal and executes $resolved. Because $target can be modified by non-administrators, any user on this machine can replace the target and gain $principal privileges the next time the task fires." `
                        -Recommendation "Restrict write access to $target, or change the task to run as a less privileged account." `
                        -Evidence ([ordered]@{
                            'Task'    = "$($task.TaskPath)$($task.TaskName)"
                            'Runs as' = $principal
                            'Target'  = $resolved
                            'Writable location' = $target
                            'Dangerous grants'  = ($acl.Grants -join ' | ')
                        })
        }
    }
}

function Test-StoredCredentials {
    Write-ScanLog -Message 'Stored credentials and secrets' -Level 'Step'

    try {
        $output = (& cmdkey /list 2>$null | Out-String)
        $targets = @([regex]::Matches($output, 'Target:\s*(?<target>.+)') | ForEach-Object { $_.Groups['target'].Value.Trim() })
        $interesting = @($targets | Where-Object { $_ -notmatch 'virtualapp/didlogical|SSO_POP_Device|WindowsLive:target=virtualapp' })

        if ($interesting.Count -gt 0) {
            Add-Finding -Category $script:AccountCategory -Check 'StoredCredentials' -Severity 'Medium' `
                        -Title "$($interesting.Count) saved credential(s) in Windows Credential Manager" `
                        -Detail 'Saved credentials can be replayed by any process running as you - no password prompt, and nothing for an antivirus to detect. Malware routinely harvests this store, and stored RDP or network-share credentials give it somewhere to move to.' `
                        -Recommendation 'Review with cmdkey /list and delete anything you do not need: cmdkey /delete:<target>. Prefer a password manager over the Windows credential store for anything sensitive.' `
                        -Evidence ([ordered]@{ 'Targets' = (($interesting | Select-Object -First 20) -join ' | ') })
        }
    }
    catch { }

    # Files whose names advertise that they hold secrets, in obvious locations.
    $searchRoots = @("$env:USERPROFILE\Desktop", "$env:USERPROFILE\Documents", "$env:USERPROFILE\Downloads")
    $patterns = @('*password*','*passwd*','*credential*','*secret*','id_rsa','*.pem','*.ppk','unattend.xml','sysprep.inf')
    $hits = New-Object System.Collections.ArrayList

    foreach ($root in $searchRoots) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($pattern in $patterns) {
            foreach ($file in (Get-ChildItem -LiteralPath $root -Filter $pattern -File -Recurse -Depth 2 -ErrorAction SilentlyContinue | Select-Object -First 5)) {
                $null = $hits.Add($file.FullName)
            }
        }
    }

    if ($hits.Count -gt 0) {
        Add-Finding -Category $script:AccountCategory -Check 'StoredCredentials' -Severity 'Low' `
                    -Title "$($hits.Count) file(s) in your profile appear to contain credentials" `
                    -Detail 'Files named for passwords or private keys sitting in Desktop/Documents/Downloads are the first thing an infostealer collects. This check only looks at filenames; it does not open the files.' `
                    -Recommendation 'Move secrets into a password manager or an encrypted volume, and delete plaintext copies.' `
                    -Evidence ([ordered]@{ 'Files' = (($hits | Select-Object -Unique -First 15) -join ' | ') })
    }
}

function Test-PrivilegeAssignments {
    <#
        .SYNOPSIS
        Dangerous user rights held by non-administrative principals.
        SeDebugPrivilege alone lets a holder open lsass.exe and dump credentials.
    #>
    Write-ScanLog -Message 'User rights assignments' -Level 'Step'

    if (-not (Test-IsElevated)) { return }

    $exportPath = Join-Path $env:TEMP "argus-secpol-$([guid]::NewGuid().ToString('N')).inf"
    try {
        $null = & secedit /export /cfg $exportPath /areas USER_RIGHTS 2>$null
        if (-not (Test-Path -LiteralPath $exportPath)) { return }

        $content = Get-Content -LiteralPath $exportPath -ErrorAction Stop

        $dangerous = @{
            'SeDebugPrivilege'              = 'debug any process, which allows reading credentials out of lsass.exe'
            'SeTakeOwnershipPrivilege'      = 'take ownership of any file or object'
            'SeBackupPrivilege'             = 'read any file on disk regardless of its permissions'
            'SeRestorePrivilege'            = 'write any file on disk regardless of its permissions'
            'SeLoadDriverPrivilege'         = 'load kernel drivers'
            'SeImpersonatePrivilege'        = 'impersonate other users, the basis of most local escalation exploits'
            'SeTcbPrivilege'                = 'act as part of the operating system'
            'SeCreateTokenPrivilege'        = 'create arbitrary access tokens'
        }
        # SIDs that are administrative or service accounts by design.
        $expectedSids = '\*S-1-5-32-544|\*S-1-5-32-551|\*S-1-5-18|\*S-1-5-19|\*S-1-5-20|\*S-1-5-6|\*S-1-5-32-568|\*S-1-5-83'

        foreach ($line in $content) {
            if ($line -notmatch '^(?<privilege>Se\w+)\s*=\s*(?<holders>.+)$') { continue }
            $privilege = $Matches['privilege']
            if (-not $dangerous.ContainsKey($privilege)) { continue }

            $holders = @($Matches['holders'] -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
            $unexpected = @($holders | Where-Object { $_ -notmatch $expectedSids })
            if ($unexpected.Count -eq 0) { continue }

            $resolved = foreach ($holder in $unexpected) {
                $sid = $holder.TrimStart('*')
                try { (New-Object Security.Principal.SecurityIdentifier($sid)).Translate([Security.Principal.NTAccount]).Value }
                catch { $holder }
            }

            Add-Finding -Category $script:AccountCategory -Check 'PrivilegeAssignments' -Severity 'High' `
                        -Title "$privilege is granted to a non-default principal" `
                        -Detail "Holders of this right can $($dangerous[$privilege]). Granted to: $($resolved -join ', ')." `
                        -Recommendation "Review in secpol.msc under Local Policies > User Rights Assignment, and remove any principal that does not need it." `
                        -Evidence ([ordered]@{
                            'Privilege'   = $privilege
                            'Unexpected holders' = ($resolved -join ', ')
                            'Raw entry'   = ConvertTo-DisplayString $Matches['holders'] 300
                        })
        }
    }
    catch { }
    finally {
        Remove-Item -LiteralPath $exportPath -Force -ErrorAction SilentlyContinue
    }
}

function Invoke-AccountChecks {
    Invoke-Check -Name 'LocalAccounts'         -Body { Test-LocalAccounts }
    Invoke-Check -Name 'PasswordPolicy'        -Body { Test-PasswordPolicy }
    Invoke-Check -Name 'UnquotedServicePaths'  -Body { Test-UnquotedServicePaths }
    Invoke-Check -Name 'WritableServiceBinary' -Body { Test-WritableServiceBinaries }
    Invoke-Check -Name 'ServicePermissions'    -Body { Test-ServicePermissions }
    Invoke-Check -Name 'PathHijacking'         -Body { Test-PathHijacking }
    Invoke-Check -Name 'TaskPrivilegePaths'    -Body { Test-ScheduledTaskPrivilegePaths }
    Invoke-Check -Name 'StoredCredentials'     -Body { Test-StoredCredentials }
    Invoke-Check -Name 'PrivilegeAssignments'  -Body { Test-PrivilegeAssignments }
}

# ============================ lib/Report.ps1 ============================
<#
    Report.ps1 - Output rendering.

    Produces a single self-contained HTML file (no external assets, so it opens
    fine on an offline or quarantined machine), plus optional JSON for
    diffing two scans against each other.
#>

function ConvertTo-HtmlText {
    param([string]$Text)

    if ([string]::IsNullOrEmpty($Text)) { return '' }
    return $Text.Replace('&', '&amp;').Replace('<', '&lt;').Replace('>', '&gt;').Replace('"', '&quot;')
}

function Get-SeverityGuidance {
    param([string]$Severity)

    switch ($Severity) {
        'Critical' { 'Act now. Each of these either indicates active compromise or hands full control of the machine to anyone who asks.' }
        'High'     { 'Investigate today. Real weaknesses or unexplained software that materially increase your risk.' }
        'Medium'   { 'Worth fixing. Hardening gaps and configuration that widens the attack surface.' }
        'Low'      { 'Tidy up when convenient. Minor exposure or good-practice items.' }
        default    { 'Context only. Recorded so you have a baseline to compare against later.' }
    }
}

function New-HtmlReport {
    param(
        [Parameter(Mandatory)][object[]]$Findings,
        [Parameter(Mandatory)][object]$HostInfo,
        [Parameter(Mandatory)][string]$OutputPath,
        [Parameter(Mandatory)][datetime]$StartedAt,
        [Parameter(Mandatory)][datetime]$FinishedAt,
        [object[]]$Errors = @(),
        [string[]]$ChecksRun = @()
    )

    $counts = @{ Critical = 0; High = 0; Medium = 0; Low = 0; Info = 0 }
    foreach ($finding in $Findings) { $counts[$finding.Severity]++ }

    $duration = [int]($FinishedAt - $StartedAt).TotalSeconds
    $ordered  = @($Findings | Sort-Object Rank, Category, Title)

    $verdict = if ($counts.Critical -gt 0) {
        'Critical findings need your attention now'
    } elseif ($counts.High -gt 0) {
        'High-severity findings need investigation'
    } elseif ($counts.Medium -gt 0) {
        'No urgent issues; hardening gaps remain'
    } else {
        'Nothing urgent found on this pass'
    }

    $verdictClass = if ($counts.Critical -gt 0) { 'bad' } elseif ($counts.High -gt 0) { 'warn' } elseif ($counts.Medium -gt 0) { 'ok' } else { 'good' }

    # ---- head / style -----------------------------------------------------
    $style = @'
<style>
